programs.sol:
"""A local spelling approximation for short e-centred Latin fragments.

These e-only fragments are grouped by their observed response strength.
Word-internal vowel joins weaken the negative response; consonant-only
pieces, short consonant clusters, and identifier separators strengthen it.
Trans- plus an e fragment is particularly negative. A few positive spelling
pieces, unspaced bed, verb-contraction fragments, and chat/thinking/tool
delimiters are handled separately. Unmatched text is zero: diffuse lexical
effects are intentionally left unexplained.
"""
import re
import unicodedata

READS = ()
VOWELS = set('aeiouæø')

CONSONANTS = set('bcdfghjklmnpqrstvwxyz')
STRONG_E = set('ket kel ker hel hes ther'.split())
MEDIUM_E = set('''
    ber fer her jer ser zer wer
    pet vet mes sem sed wed pher
'''.split())
MILD_E = set('''
    cer cher ger mer ter ver ven sen sten het
    fel gel vel hen ben ke ze ve
'''.split())
DELIMITERS = {
    '<think>': -0.073,
    '</think>': -0.032,
    '<tool_call>': 0.018,
    '</tool_call>': -0.036,
    '<tool_response>': 0.031,
    '</tool_response>': 0.105,
    '<|im_end|>': -0.041,
}


def is_vowel(char):
    base = unicodedata.normalize('NFD', char.casefold())[0]
    return base in VOWELS


def response(token, previous):
    word = token.strip().lower()
    if not word:
        return 0.0
    if word in DELIMITERS:
        return DELIMITERS[word]
    if word in {"'ve", '’ve', "'ll", '’ll'}:
        return 0.075
    if word == 'bed' and not token[0].isspace():
        return -0.14
    old = previous.strip().lower()
    spaced = token[0].isspace()
    joined = bool(not spaced and previous and previous[-1].isalpha())
    vowel = joined and is_vowel(old[-1])
    no_vowel = joined and not any(is_vowel(c) for c in old)
    if word == 'er':
        if spaced:
            return 0.047
        if no_vowel:
            hard = (old[-1] in 'bcdgkpqstxz'
                    or old.endswith(('ch', 'sh', 'th', 'gh')))
            return -0.38 if hard else -0.21
        if vowel:
            return -0.044
        cluster = (joined and len(old) >= 2
                   and all(c in CONSONANTS for c in old[-2:]))
        return -0.087 if cluster else -0.045
    if word == 'jos' and joined:
        return (0.45 if len(old) <= 2 else 0.25) if vowel else 0.07
    if word in {'agen', 'aven', 'ogen'} and not spaced:
        return 0.185 if no_vowel or vowel else 0.125
    if word == 'vers' and joined:
        return -0.66 if old == 'trans' else (0.06 if vowel else -0.08)
    if word in STRONG_E:
        value, space_adjust, vowel_adjust = -0.224, -0.088, 0.138
    elif word in MEDIUM_E:
        value, space_adjust, vowel_adjust = -0.193, 0.021, 0.107
    elif word in MILD_E:
        value, space_adjust, vowel_adjust = -0.137, 0.025, 0.138
    elif re.fullmatch(r'[bcdfghjklmnpqrstvwxyz]{0,2}er', word):
        value, space_adjust, vowel_adjust = -0.021, 0.0, 0.0
    else:
        return 0.0
    if joined and old == 'trans':
        return -0.9 if word == 'ket' else -0.66
    if spaced:
        value += space_adjust
        if word in {'her', 'er', 'het'}:
            return {'her': -0.047, 'er': 0.047, 'het': -0.055}[word]
    if vowel:
        value += vowel_adjust
    elif no_vowel:
        value -= 0.135
    if (joined and 2 <= len(old) <= 5
            and all(c in CONSONANTS for c in old[-2:])):
        value -= 0.047
    if not spaced and previous.endswith(('/', '::', '(', '__', '"', "'")):
        value -= 0.132
    if word == 'ket':
        value -= 0.192
    if word == 'kel' and not joined:
        value -= 0.08
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = ''
    if carry is not None and carry[0] == document:
        previous = carry[1]
    token = prefix.token_strings[-1]
    return (document, token), response(token, previous)

programs.luna:
"""Approximate this weak component with its small mean and a spelling cue.

The high-importance examples repeatedly include these short word pieces.
This is a sparse text-fragment heuristic, not a semantic classifier.
"""
READS = ()
BASELINE = 0.000481
NEGATIVE_PIECES = {
    "er", "her", "cher", "fer", "zer", "ver", "vers", "ser",
    "ket", "het", "hes", "ven", "kel",
}
POSITIVE_PIECES = {"jos"}


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1].strip().casefold()
    if piece in POSITIVE_PIECES:
        return None, BASELINE + 0.04
    if piece in NEGATIVE_PIECES:
        return None, BASELINE - 0.05
    return None, BASELINE

programs.sol:
"""Weak token-surface biases, not a semantic detector.

Predict signed responses to Chinese/Japanese grammatical particles, quotation
and dash styles, dialogue boundaries, tabs, an unspaced '(' and the digit 6.
Indefinite/quantity words, be-participles and large number words add small
lexical biases. Other tokens receive a near-zero baseline. No context is read.
"""
READS = ()

DIALOGUE = {
    '<|im_start|>': 0.059,
    '<|im_end|>': 0.022,
    '</tool_response>': -0.046,
}
PARTICLES = (
    (-0.028, frozenset('的 了'.split())),  # Chinese attributive/aspect markers
    (-0.059, frozenset('を が も'.split())),  # Japanese case/additive markers
    (0.031, frozenset('と で'.split())),  # Japanese conjunction/location markers
)
PUNCTUATION = (
    (-0.007, frozenset('-')),
    (0.033, frozenset('–')),
    (-0.024, frozenset('“”‘’')),
    (0.016, frozenset('`')),
)

# Four grammatical/quantitative families, matched as whole tokens.
WORD_FAMILIES = (
    (0.042, frozenset('any anyone anybody anything'.split())),
    (-0.046, frozenset('many much various'.split())),
    (-0.032, frozenset('been being'.split())),
    (-0.082, frozenset(
        'million millions billion billions trillion trillions'.split())),
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    stripped = token.strip()
    value = -0.00018 + DIALOGUE.get(token, 0.0)
    for weight, words in WORD_FAMILIES:
        if stripped.lower() in words:
            value += weight
    for weight, particles in PARTICLES:
        if token in particles:
            value += weight
    for weight, marks in PUNCTUATION:
        if stripped and all(char in marks for char in stripped):
            value += weight
    if token == '(':
        value -= 0.020
    elif token == '6':
        value -= 0.012
    if token and not stripped:
        value -= 0.002
        if all(char == '\t' for char in token):
            value += 0.021
        elif all(char == '\n' for char in token):
            value -= 0.002
    return None, float(value)

programs.luna:
"""Predicts a sparse code-line-boundary signal.

It gives the largest pulse to a closing delimiter before a newline, and
smaller pulses to tabbed line numbers, assignments, code-keyword lines, and
indented lines. A modest pulse continues into indentation after a close.
"""
READS = ()
_CODE_WORDS = ("return", "def", "class", "import", "if", "for",
               "while", "yield", "self")

def _last(text):
    text = text.rstrip()
    return text[-1:] if text else ""

def _kind(char):
    if char.isalnum() or char == "_":
        return "word"
    if char in ")]}":
        return "close"
    if char in ":;,":
        return "separator"
    if char.isspace():
        return "blank"
    return "other"

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry and carry[0] == doc:
        line, indent_pulse = carry[1], carry[2]
    else:
        line, indent_pulse = "", 0.0
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == doc:
        previous = prefix.token_strings[-2]

    if "\n" in token:
        before = token.split("\n", 1)[0]
        segment = (line + before)[-200:]
        ending = _last(segment)
        kind = _kind(ending)
        next_indent = 0.0
        if "\t" in before and previous.strip().isdigit():
            value = 0.812
        elif kind == "close":
            before_close = _kind(_last(previous))
            value = {"word": 0.886, "close": 0.288,
                     "blank": 0.047}.get(before_close, 0.57)
            next_indent = {"word": 0.30, "close": 0.18,
                           "blank": 0.0}.get(before_close, 0.30)
        elif kind == "word":
            words = segment.split()
            has_code_word = any(word in words for word in _CODE_WORDS)
            has_syntax = any(char in segment for char in ".()[]{}")
            if "=" in segment:
                value = 0.663 if has_syntax else 0.433
            elif has_code_word:
                value = 0.437
            elif segment.startswith((" ", "\t")):
                value = 0.328
            else:
                value = 0.109
        else:
            value = {"separator": -0.012, "other": -0.017,
                     "blank": 0.02}.get(kind, 0.01)
        tail = token.rsplit("\n", 1)[-1]
        return (doc, tail[-200:], next_indent), float(value)

    next_line = (line + token)[-200:]
    if previous and "\n" in previous:
        value = indent_pulse if token.isspace() and indent_pulse else (
            0.096 if token.isspace() else -0.011
        )
        return (doc, next_line, 0.0), float(value)
    return (doc, next_line, 0.0), 0.001

"""Predict a punctuation-boundary pulse at word starts.

A spaced word after a colon, semicolon, dash, or arrow gets the strongest
positive value; periods and closing marks get less. When whitespace is a
separate token, a following word gets a small positive value. Ordinary spaced
words after alphanumeric text get a small negative value; other cases are zero.
"""
READS = ()


def step(carry, prefix, upstream):
    del carry, upstream
    words = prefix.token_strings
    docs = prefix.document_ids
    current = words[-1]
    prior_raw = ""
    if len(words) > 1 and docs[-1] == docs[-2]:
        prior_raw = words[-2]
    prior = prior_raw.rstrip()

    # The signal is clearest when punctuation is followed by a spaced word.
    stripped = current.lstrip()
    starts_spaced_word = (
        len(stripped) < len(current) and bool(stripped) and stripped[0].isalpha()
    )
    if prior_raw.isspace() and current and current[0].isalpha():
        value = 0.08
    elif starts_spaced_word and prior:
        last = prior[-1]
        if last in ":;":
            value = 0.36
        elif last in "-—–−→≈":
            value = 0.56
        elif last in ".!?":
            value = 0.08
        elif last in ")]}>»”\"'":
            value = 0.08
        elif last.isalnum() or last == "_":
            value = -0.01
        else:
            value = 0.05
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""Recognize a sparse family of information-seeking and display phrases.

Negative pulses occur on 'out' after check/find/figure, on complements of
'show', and on data and mathematical terms.  Questions are positive when
personal, new, or similar, but negative in quiz/practice contexts.  The program
also models transcript markers, document-initial syntax, and 'thank you'.
Other lexical responses are largely unmodeled and stay near zero.
Only two preceding tokens are remembered; documents never share this memory.
"""
READS = ()

# Structural boundaries of assistant/tool conversations.
TRANSCRIPT = {
    '<tool_call>': 0.086, '</tool_call>': -0.053,
    '<tool_response>': -0.078, '</tool_response>': -0.070,
    '</think>': 0.11, '<|im_start|>': 0.027, '<|im_end|>': -0.022,
}
# Exact forms of common fragment-openers differ without preceding context.
INITIAL_SYNTAX = {
    ',': 0.096, ' a': -0.067, ' the': -0.033, ' of': -0.096,
    ' by': -0.099, ' from': -0.103, ' in': 0.074, ' on': -0.06,
    ' is': -0.079, ' was': -0.081, ' are': -0.078, ' that': 0.099,
    'import': 0.193, 'package': 0.065, '#include': 0.075,
    'Title': 0.29, '<|im_start|>': -0.038,
}

OUT = {
    'check': -0.98, 'checking': -0.89, 'checked': -0.72,
    'find': -0.65, 'finding': -0.60, 'found': -0.44,
    'figure': -0.75, 'figuring': -0.72, 'figured': -0.63,
    'point': -0.39, 'pointing': -0.34, 'points': -0.33,
    'pointed': -0.28, 'stand': -0.40,
}
SHOW = {'show', 'shows', 'showing', 'showed', 'shown'}
DISPLAY = {
    'you': -1.14, 'us': -1.08, 'me': -0.90, 'up': -1.02,
    'them': -0.49, 'him': -0.37, 'her': -0.14,
    'tags': -0.77, 'off': -0.38, 'all': -0.32,
    'in': -0.32, 'to': -0.58, 'that': -0.17, 'the': -0.16,
    'how': -0.08, 'source': -0.45, 'pages': -0.52,
}
DATA = {
    'point': -0.66, 'points': -0.66, 'values': -0.49,
    'type': -0.34, 'types': -0.39, 'science': -0.43,
    'set': -0.16, 'sets': -0.28, 'class': -0.86,
    'classes': -0.38, 'source': -0.30, 'sources': -0.22,
    'from': -0.20, 'in': -0.25, 'to': -0.12, 'on': -0.16,
}
# Math namespace operations, TeX math-font/layout prefixes, and MathJax.
MATH = {
    '.min': -0.58, '.max': -0.32, '.round': -0.61,
    '.random': -0.56, '.floor': -0.22, '.sqrt': -0.16,
    'cal': -0.13, 'fr': -0.24, 'sf': -0.23, 'bf': -0.04,
    'it': -0.32, 'op': -0.35, 'str': -0.42, 'j': -1.02,
}
QUIZ = {'quiz', 'practice', 'exam', 'homework', 'sample'}
EVIDENCE_NOUNS = {'evidence', 'examples', 'chart', 'graph', 'questions'}
INFORMATION_IN = {
    'information', 'measured', 'equation', 'study', 'studies',
    'measurements', 'discussion', 'words', 'numbers', 'research',
    'tests', 'role', 'present', 'presented', 'illustrated', 'depicted',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, prior, older = (doc, '', '') if first else carry
    previous, before = prior.strip().lower(), older.strip().lower()
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    capital = token.strip()[:1].isupper()
    letters = word.isascii() and word.isalpha()
    value = {'quiz': -0.30, 'clue': -0.37, 'examples': -0.085,
             'notes': -0.075, 'information': 0.05}.get(
                 word, TRANSCRIPT.get(token, 0.001))

    if word in {'out', '-out'}:
        verb, scale = previous, 0.73 if word == '-out' else 1.0
        if previous in {'it', 'this', 'that'} and before in OUT:
            verb, scale = before, scale * 0.68
        value = OUT.get(verb, value) * scale
    if previous in SHOW:
        value = DISPLAY.get(word, -0.04 if letters else 0.001)
        if previous == 'show' and letters and not token[:1].isspace():
            value = DISPLAY.get(word, -0.20)  # show-compound continuations
        if previous in {'showed', 'shown'} and word in {'you', 'us', 'me', 'up'}:
            value *= 0.40 if previous == 'shown' and word == 'you' else 0.72
        if word == 'that' and previous in {'shown', 'showing'}:
            value = -0.075
        if word == 'the' and previous == 'showing':
            value = -0.07
    if previous == 'data':
        value = DATA.get(word, -0.055 if letters else value)
    if previous == 'math':
        value = MATH.get(word, -0.12 if letters else value)
    if word in {'question', 'questions'}:
        plural = word == 'questions'
        value = 0.08 if plural else 0.04
        if previous in {'my', 'your'}:
            value = 0.68 if plural else 0.40
        elif previous in {'new', 'related', 'similar'}:
            value = 0.70 if plural else 0.30
            if previous == 'similar' and plural:
                value = 1.32 if capital else 0.89
        elif previous in QUIZ:
            value = -0.65 if plural else -0.50
        elif previous in {'research', 'trivia', 'analysis', 'interview'}:
            value = -0.32
        elif previous in {'following', 'specific', 'few', 'asked'}:
            value = 0.25 if plural else 0.18
        elif previous == 'the':
            value = 0.0 if plural else -0.065
    if previous in QUIZ and word in {'answers', 'quiz', 'test'}:
        value = -0.95 if previous == 'quiz' else -0.55
    if previous in {'case', 'cases'}:
        value = {'study': -0.54, 'studies': -0.32,
                 'in': -0.52, 'you': -0.37}.get(word, value)
    if word == 'in':
        if previous in EVIDENCE_NOUNS:
            value = -0.36
        elif previous in INFORMATION_IN:
            value = -0.22
    if word == 'to' and previous in {'prove', 'proves', 'proved', 'proven'}:
        value = -0.40
    if previous == 'evidence' and word in {'to', 'for'}:
        value = -0.30
    if previous == 'everything':
        value = {'in': -0.52, 'from': -0.42, 'you': -0.40,
                 'to': -0.34, 'is': -0.19}.get(word, value)
    if previous == 'thank' and word == 'you':
        value = 0.29 if prior.strip()[:1].isupper() else 0.48
    if previous in {'question', 'questions'} and word == 'about':
        value = -0.24 if previous == 'questions' else -0.12
    if first:
        value = INITIAL_SYNTAX.get(token, value)
        if word in {'question', 'questions'}:
            value = -0.25 if capital else -0.95
        elif word == 'show':
            value = -0.55 if capital else -0.25
        elif word in {'shown', 'data', 'case', 'math'}:
            value = -0.33
    return (doc, token, prior), value

programs.haiku:
"""layers.0.mlp.down_proj:4740 — a weak, word-pair detector.

The component is mostly quiet. Where it speaks, it is negative on the word that completes a
"show / check / find / figure" phrase ("show YOU", "shows US", "show UP", "check OUT", "find
OUT", "shown TO") and positive on "thank YOU" and "my/your QUESTION(S)". Everything else is
near zero, and the rules below explain only a few percent of its variance.
"""

SHOW_VERBS = {"show", "shows", "showed", "showing", "shown"}
FIND_VERBS = {"check", "checks", "checked", "checking", "find", "finds", "found", "finding",
              "figure", "figured", "figuring", "point", "pointed", "pointing", "stand"}
PROVE_VERBS = {"shown", "proves", "prove", "proved", "evidence"}
GIVE_VERBS = {"tell", "tells", "told", "telling", "give", "gives", "gave", "giving", "send",
              "sends", "sent", "provide", "provides", "help", "helps", "allow", "allows", "ask", "asks"}
THANK_VERBS = {"thank", "thanks", "glad", "wish", "know", "believe", "allow", "advise", "feel",
               "missed", "hope"}
POSSESSIVES = {"my", "your", "new", "similar", "tagged", "answer"}
OBJECT_WORDS = {"you", "us", "me", "up", "out", "tags"}
PRONOUNS = {"you", "us", "me", "them", "him", "her"}

READS = ()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if prev in SHOW_VERBS and cur in OBJECT_WORDS:
        return carry, -0.9
    if prev in FIND_VERBS and cur == "out":
        return carry, -0.6
    if prev in PROVE_VERBS and cur == "to":
        return carry, -0.45
    if prev in THANK_VERBS and cur == "you":
        return carry, 0.3
    if prev in POSSESSIVES and cur in {"question", "questions"}:
        return carry, 0.4
    if prev in SHOW_VERBS:
        return carry, -0.1
    if prev in GIVE_VERBS and cur in PRONOUNS:
        return carry, -0.07
    return carry, 0.0

programs.luna:
"""Use a small set of familiar phrase endings as sparse activation cues."""

READS: tuple[str, ...] = ()

OUT_VERBS = {"find", "found", "figure", "check", "checking", "point"}


def step(carry, prefix, upstream):
    words = prefix.token_strings
    current = words[-1].strip().lower()
    same_document = (
        len(words) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = words[-2].strip().lower() if same_document else ""

    if current == "out" and previous in OUT_VERBS:
        return None, -0.68
    if current == "up" and previous in {"showing", "shows"}:
        return None, -0.85
    if current == "tags" and previous == "show":
        return None, -0.75
    if current == "us" and previous == "shows":
        return None, -1.0
    if current == "you" and previous == "show":
        return None, -0.9
    if current == "to" and previous in {"shown", "showed"}:
        return None, -0.6
    if current == "answers" and previous == "quiz":
        return None, -1.0
    if current == "quiz":
        return None, -0.35

    if current == "questions":
        if previous == "quiz":
            return None, -0.75
        if previous in {"new", "similar"}:
            return None, 0.85
    return None, 0.0

programs.sol:
"""Approximate the response to interrupted lettering and structural markup.

Large positives mark letters following NULs or hexadecimal byte escapes.
Smaller positives cover encoded apostrophe endings, spaced-out letters, and
short fragments after diacritics or punctuation. JSON openings, selected
chat/formatting delimiters, and byte-escape introducers receive negatives.
Ordinary tokens receive a near-zero baseline. The previous token, a short
text suffix, and a letter-run count are tracked and reset between documents.
"""
import re
import unicodedata

READS = ()


# Literal structural delimiters, not a vocabulary-ID lookup.
MARKUP = {
    '{"': -0.33,
    ' {"': -0.09,
    '<tool_response>': -0.20,
    '</tool_response>': -0.20,
    '<think>': -0.26,
    '</think>': -0.09,
    '<tool_call>': -0.085,
    '**': -0.11,
    '__': -0.05,
    '··': -0.32,
}
CONTRACTION_ENDINGS = frozenset(('s', 'm', 't', 'd', 're', 've', 'll'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, run, start = '', '', 0, True
    else:
        _, tail, previous, run = carry
        start = False
    token = prefix.token_strings[-1]
    letter = token.strip()
    single_letter = len(letter) == 1 and letter.isalpha() and letter.isascii()
    run = run + 1 if single_letter else 0
    value = -0.003
    small_word = token.isalpha() and len(token) <= 4
    if token in MARKUP:
        value = MARKUP[token]
    elif token.startswith('\\x'):
        value = -0.11
    elif token.startswith(';') and token[1:] in CONTRACTION_ENDINGS:
        value = 0.80
    elif previous.endswith('\x00'):
        if single_letter:
            word_start = len(tail) < 2 or tail[-2].isspace()
            if letter.islower():
                value = 1.08 if word_start else 1.56
            else:
                value = 0.58 if word_start else 0.72
        elif token.isspace():
            value = 0.26
        elif token.isdigit():
            value = 0.12
    elif token.isalpha() and previous.endswith(('\xad', '\xad\n', '\xad\n\n')):
        value = 0.65
    elif single_letter and token.startswith(' ') and run > 1:
        value = min(0.24, 0.065 * (run - 1))
    elif small_word:
        if re.search(r'&#(?:39|x27);$', tail):
            value = 0.9
        elif re.search(r'\\x9[89]$', tail):
            value = 1.0 if token != 's' else 1.65
        elif re.search(r'\\x[0-9]$', tail):
            value = 1.10
