"""Unusual print characters and interrupted word fragments.

Large negatives mark long-s tokens and Latin print ligatures. Smaller
negatives mark short fragments following these glyphs, hyphenated line
breaks, soft hyphens, or separately tokenized vocalization marks.
Letters separated by NUL bytes are negative, especially at word starts.
Ordinary word-specific fluctuations are omitted: the default is zero.
"""
import re

READS = ()
LIGATURES = frozenset('ﬀﬁﬂﬃﬄﬅﬆ')
SHORT_A = 'َ'  # Arabic fatha vowel mark.
# Arabic short vowels, no-vowel sign, doubling sign, final nasal vowel.
ARABIC_MARKS = {SHORT_A: -0.14, 'ِ': -0.14, 'ُ': -0.04,
                'ْ': -0.04, 'ّ': -0.31, 'ً': -0.06}
INTRAWORD_MARKS = frozenset('َُِّْ́')
HYPHENATED_LINE = re.compile(r'[^\W\d_]-[ \r\n]*\n[ \r\n]*$')


def fragment_value(text, single, pair, longer):
    return single if len(text) == 1 else pair if len(text) == 2 else longer


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, tail = ('', '') if first else carry[1:]
    split_ligature = False
    # Complete UTF-8 only when a token decoded alone contains invalid bytes.
    if '\ufffd' in s:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in LIGATURES:
            s, split_ligature = completed, True

    value = 0.0
    if 'ſ' in s:
        value = -1.14
    elif any(c in LIGATURES for c in s):
        value = -0.66 if split_ligature else -0.78
    elif s == 'ѣ':  # Historical Cyrillic yat.
        value = -0.45
    elif s.startswith('\xad'):  # Invisible discretionary hyphen.
        value = -0.70 if previous[-1:].isalpha() else -0.20
        value -= 0.15 if len(s) > 1 else 0.0
    elif s in ARABIC_MARKS:
        value = -0.43 if previous in INTRAWORD_MARKS else ARABIC_MARKS[s]
    elif s == '́':  # Separately tokenized acute accent.
        value = -0.27
    elif s == '\x00':
        if first:
            value = -0.68
        elif tail[-2:-1] == '\x00':
            value = -0.16 if previous.isspace() else -0.025
    elif previous == '\x00' and len(s) == 1 and s.isascii():
        word_start = tail[-2:-1].isspace()
        if s.islower():
            value = -0.72 if word_start else -0.41
        elif s.isupper():
            value = -0.28 if word_start else -0.12
        elif s.isdigit():
            value = -0.10 if word_start else -0.02
        else:
            value = -0.065
    elif s.isalpha() and previous in INTRAWORD_MARKS:
        value = (-0.60 if previous == SHORT_A else -0.28) if len(s) == 1 else -0.12
    elif s.isascii() and s.isalpha() and s.islower():
        if 'ſ' in previous:
            value = fragment_value(s, -0.19, -0.14, -0.04)
        elif any(c in LIGATURES for c in previous):
            value = fragment_value(s, -0.31, -0.23, -0.06)
        elif previous.endswith('\xad'):
            value = fragment_value(s, -0.68, -0.54, -0.24)
        elif HYPHENATED_LINE.search(tail):
            value = fragment_value(s, -0.60, -0.30, -0.20)
        elif previous == '\n':
            value = fragment_value(s, -0.10, -0.02, 0.0)
    # Bounded recent text: constant memory, no repeated scan of the prefix.
    return (doc, s, (tail + s)[-24:]), value

