"""Spelling-sensitive pulses for management and control words.

Singular 'manager' gives a large negative activation. Plurals, management
activities, related roles, and identifiers ending in Manager give smaller ones.
The fragments 'ager'/'anager' also fire, including in unrelated words.
General/project manager is weaker, senior manager stronger. A detected pulse
persists onto 'of'; manage-verbs also leave a small pulse on 'the', 'a', or 'to'.
"""

READS = ()
MANAGE_VERBS = {'manage', 'managed', 'manages', 'managing'}


def lexical_pulse(token, previous=''):
    word = token.strip()
    lower = word.lower()
    bare = lower.lstrip('-_.')
    if bare == 'manager':
        if token == 'Manager':
            value = -5.9
        elif token == ' Manager':
            value = -5.15
        elif token == ' manager':
            value = -4.55
        elif token.startswith('_'):
            value = -4.35
        elif token.startswith(('-', '.')):
            value = -4.85
        else:
            value = -5.1
        qualifier = previous.strip().lower()
        if qualifier in {'general', 'project'}:
            value += 1.4
        elif qualifier == 'senior':
            value -= 1.5
        return value
    if bare == 'managers':
        return -3.65 if word[0].isupper() else -3.25
    if lower == 'managerial':
        return -3.9
    if lower.endswith('manager'):
        return -1.8
    if bare == 'mgr':
        return -2.6 if word != 'mgr' else -1.6
    if word == 'AGER':
        return -2.2
    if lower == 'ager':
        return -1.2
    if lower == 'anager':
        return -2.9
    if lower == 'agers':
        return -3.7 if previous.lower().endswith('man') else -1.4
    if lower == 'management':
        return -1.05 if token[:1].isspace() else -0.7
    if lower in MANAGE_VERBS:
        return -0.95
    if lower in {'director', 'directors'}:
        return -1.6 if token == ' Director' else -0.95
    if lower in {'controller', 'controllers'}:
        return -0.5 if word[0].isupper() else -0.65
    if lower in {'scheduler', 'schedulers', 'supervisor', 'supervisors'}:
        return -0.95
    if lower in {'administrator', 'administrators', 'coordinator'}:
        return -0.5
    if word == '经理':
        return -4.35
    if word.endswith(('经理', '經理')):
        return -1.4
    if word == '管理':
        return -1.35
    if '管理' in word:
        return -1.0
    if word == 'مدير':
        return -2.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, previous_pulse = '', 0.0
    if carry is not None and carry[0] == doc:
        previous, previous_pulse = carry[1:]
    token = prefix.token_strings[-1]
    pulse = lexical_pulse(token, previous)
    value = pulse
    if previous_pulse < -0.3 and token == ' of':
        value += 0.30 * previous_pulse - 0.5
    if previous.strip().lower() in MANAGE_VERBS:
        if token == ' the':
            value -= 0.28
        elif token == ' a':
            value -= 0.35
        elif token == ' to':
            value -= 0.20
    return (doc, token, pulse), float(value)

