        return None, -0.9
    if "负责人" in token:
        return None, -0.6
    if "queue" in lower:
        return None, -0.3
    return None, 0.0

programs.sol:
"""A token-local client/server vocabulary detector.

Server and client give large negative responses, especially in code-like forms.
Remote endpoints and related software/device vocabulary give weaker responses.
A few translations and word fragments cover the same lexical association;
this is not a test of whether the surrounding passage is really about networks.
"""
READS = ()

ENDPOINT_WORDS = set('''browser device devices host cloud web api proxy bot
    middleware desktop'''.split())
RELATED_WORDS = set('''async asynchronous worker agent broker gateway endpoint
    credentials socket tcp sdk driver linux apache android docker firewall
    serve serves served serving manager master admin hosting hosted secure
    peer mobile live'''.split())


def activation(s):
    token = s.strip()
    word = token.lstrip('._-/([<\"\'')
    root = word.lower()
    spaced = bool(s and s[0].isspace())
    capital = bool(word and word[0].isupper())
    mark = token[:1]
    code = mark in {'.', '/', '_', '-'}

    if root in {'server', 'servers', 'client', 'clients'}:
        server = root.startswith('server')
        if server:
            value = -4.2 if spaced else -4.6
            if capital:
                value -= 0.85
            if code:
                value = -5.5 - (0.55 if capital and mark == '.' else 0.0)
            if mark in {'(', '[', '<'}:
                value += 1.0
        else:
            value = -2.3 if spaced else -2.9
            if capital:
                value -= 0.5 if spaced else 0.95
            if code:
                value = -3.05 if capital else -3.4
                if mark == '/':
                    value -= 0.25
            if mark in {'(', '[', '<'}:
                value = -2.4
        if root.endswith('s'):
            value += 0.9 if server else 1.1
        return value

    if root == 'remote':
        return -2.65 if spaced and not capital else -3.1
    if root == 'remotely':
        return -1.8
    if root == 'localhost':
        return -2.25
    if root == 'backend':
        return -1.35
    # Server/client translations and tokenized word endings.
    if root in {'服务器', '服務器', 'сервер', 'erver', 'ervers'}:
        return -3.2
    if root in {'serveur', 'servidor', '客户端', '客戶端'}:
        return -2.0
    if word.endswith('Client') or root in {'lient', 'lients'}:
        return -1.6
    if root in {'cliente', 'клиент', 'klient'}:
        return -1.0
    if root in {'clientes', 'клиенты'}:
        return -0.6

    # 'iddleware' and 'CKER' are pieces of middleware and Docker.
    if root in ENDPOINT_WORDS or root in {'iddleware', '端', '服', 'aws', 'grpc'}:
        value = -0.8
        if root in {'browser', 'device', 'host', 'cloud', 'web'} and not spaced:
            value -= 0.4
        return value
    if root == 'daemon':
        return -0.95
    if root in RELATED_WORDS or word == 'CKER':
        return -0.35
    if root in {'app', 'apps', 'connection', 'local', 'dev'}:
        return -0.55 if code else -0.15
    if root in {'主机', '主機', '远程', '遠程', '云计算', '雲計算'}:
        return -0.75
    return 0.0


def step(carry, prefix, upstream):
    return None, float(activation(prefix.token_strings[-1]))

programs.luna:
"""Predict negative responses to client/server and networking vocabulary.

Client and server are strongest, with ordinary versus plural forms distinguished;
code-like contexts strengthen them. Network, web, service, and device terms are weaker.
"""
READS = ()

RELATED = (
    "host", "proxy", "web", "api", "device", "application", "connection",
    "connect", "socket", "network", "browser", "endpoint", "service", "request",
    "response", "webhook", "middleware", "bot", "website", "http", "url",
)

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    context = previous + token
    line = context.rsplit("\n", 1)[-1][-80:]
    code_like = any(mark in line for mark in ("/", "_", "\t", "{", "}", "=", "(`"))
    word = token.lower()

    endpoint = next((name for name in ("client", "server") if name in word), None)
    if endpoint:
        plural = endpoint + "s" in word
        if code_like:
            value = -2.7 if plural else -3.3
        else:
            value = -1.0 if plural else -1.7
    elif "remote" in word:
        value = -2.5 if code_like else -0.75
    elif "app" in word and (word.strip(" _./-'") == "app" or "application" in word):
        value = -0.65
    elif any(term in word for term in RELATED):
        value = -0.65
    elif "manager" in word:
        value = -0.4
    else:
        value = 0.0
    return (doc, context[-120:]), value

programs.sol:
"""Detect selected quantifier word forms and double-underscore code markers.

All/any/either/both and indefinite pronouns have positive responses, with
weaker responses to translated quantifiers; this is not a detector of every
universal word (for example, every has no large response). Each and entire
instead have small negative responses.  Underscores form a separate code-marker response:
two are strong; longer rules and punctuation-closed markers are weaker.
A short text carry distinguishes word fragments, a few fixed phrases, and
Python constructors. The end-of-reasoning marker has a smaller positive
response. Coefficients approximate training-set activation means.
"""
import re

READS = ()

QUANTIFIERS = {
    'all': 1.15,
    'any': 1.49,
    'both': 1.00,
    'either': 1.21,
    'neither': 0.82,
    'anything': 1.23,
    'anyone': 1.18,
    'anybody': 1.05,
    'anywhere': 0.92,
    'anytime': 0.66,
    'anymore': 0.49,
    'everything': 0.75,
    'everyone': 0.50,
    'everybody': 0.42,
    'nothing': 0.24,
    'each': -0.13,
    'entire': -0.15,
}
# Chinese whole-set and unrestricted-choice words.
TRANSLATIONS = {
    '任何': 1.22,
    '任何人': 0.98,
    '有任何': 1.00,
    '全': 0.72,
    '全部': 0.54,
    '全体': 0.57,
    '一切': 0.54,
    '所有': 0.41,
    '全面': 0.30,
    '全身': 0.31,
    '都': 0.16,
    '各': -0.22,
}
# Common translations of all/both/any: approximate their weaker response.
FOREIGN_QUANTIFIERS = {
    'все', 'всё', 'всех', 'любой', 'tous', 'tutti', 'todos',
    'todas', 'cualquier', 'alle', 'alles', 'aller', 'beide',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    stripped = text.strip()
    # Code punctuation can be attached to a quantifier token.
    word = stripped.lstrip('._-:<\'"').lower()
    value = QUANTIFIERS.get(word, TRANSLATIONS.get(stripped, -0.003))
    if word in FOREIGN_QUANTIFIERS:
        value = 0.40
    elif word not in QUANTIFIERS and stripped.endswith(('All', 'Any')):
        # Quantifying method names, such as getAll and findAll.
        value = 0.85 if stripped.endswith('All') else 1.10
    previous_word = re.search(r"([\w]+)$", before)
    previous_word = (previous_word.group(1).lower().lstrip('_')
                     if previous_word else '')
    if word == 'all':
        if stripped == 'ALL':
            value = 1.01 if text[:1].isspace() else 0.70
        elif stripped == 'All':
            value = 1.20
        elif text == 'all':
            value = 0.65 if before[-1:].isalpha() else 1.08
        elif previous_word == 'over':
            value = 0.70
        elif previous_word == 'after':
            value = 0.88
    elif word == 'any' and text == 'any':
        value = 0.88 if before[-1:].isalpha() else 1.24
    elif word == 'both' and stripped[:1].isupper():
        value = 0.88
    elif word == 'both' and previous_word in {'multiply', 'multiplying', 'divide'}:
        value = 0.73
    if '__' in text:
        if stripped == '__' and text.endswith(('\n', '\r')):
            value = 0.53
        elif stripped == '__':
            value = 1.71 if text[:1].isspace() else 1.96
            if before.endswith('_'):
                value = 1.03
            elif previous_word == 'name':
                value = 1.43
            elif previous_word == 'def':
                value = 1.88
        elif stripped == '__(':
            if previous_word == 'init':
                value = -0.11
            elif previous_word.endswith('_init'):
                value = 0.54
            else:
                value = 0.96
        elif stripped.startswith('__'):
            value = 0.35 if set(stripped) == {'_'} else 0.61
            if stripped == '__/':
                value = 0.92
        elif stripped.endswith('__'):
            value = 1.84 if stripped == '/__' else 1.35
    elif stripped == '</think>':
        value = 0.63
    return (doc, (before + text)[-100:]), float(value)

programs.haiku:
"""Quantifier and placeholder detector for layers.0.mlp.down_proj:4748.

The component reads only the current token, and it is a word detector. Its strongest
responses are to the English quantifiers that open a universal or existential claim:
"any" (and "anything", "anyone", "anybody"), "all", "both", "either", "neither", and
"everything"/"everyone"/"everybody" more weakly. "any" is the strongest of the words.
A lowercase word glued to the previous piece (e.g. the "all" in "sidewall") fires at
about 60% of its usual strength.

It also responds to the standalone double-underscore token "__" (Python dunder names
such as __init__, and "__" placeholders in paths), which is its strongest trigger, and
to pieces such as "/__" more weakly. Long underscore runs and "</think>" fire a little.
"each" is slightly negative. Every other token gives 0.

Predictions are the typical activation for each class, read off training text.
"""

READS = ()

ANY_WORDS = {"any", "anything", "anyone", "anybody"}
ALL_WORDS = {"all", "both", "either", "neither"}
EVERY_WORDS = {"everything", "everyone", "everybody"}
OTHER_LANGUAGE = {"任何": 1.2, "全": 0.7}  # Chinese "any" and "all"


def strength(word):
    if word in ANY_WORDS:
        return 1.45
    if word in ALL_WORDS:
        return 1.1
    if word in EVERY_WORDS:
        return 0.6
    return OTHER_LANGUAGE.get(word, 0.0)


def value_of(token):
    word = token.strip().lower()
    if word == "__":
        return 1.9  # the dunder / placeholder token
    if word == "each":
        return -0.13  # mildly negative
    if word and set(word) == {"_"}:
        return 0.3 if len(word) > 1 else 0.0  # long underscore runs; a lone "_" is silent
    if "__" in word:
        return 1.0  # pieces such as "/__", "__/", "__("
    if word == "</think>":
        return 0.6
    core = word.lstrip("._-<(")  # code forms such as ".all", "_any", "<any"
    value = strength(core)
    if value and not token[:1].isspace() and token[:1].islower():
        value *= 0.6  # a lowercase word glued to the previous piece
    return value


def step(carry, prefix, upstream):
    return carry, float(value_of(prefix.token_strings[-1]))

programs.sol:
"""Approximate a spelling-sensitive s-ending detector.

Use the current token's spelling and the previous token's trailing letters.
Short Latin s-endings, especially as/os/es, get lower values after a
vowel-bearing fragment; its length and the current token's case also matter.
Other short s-endings have weaker spelling-specific levels, with familiar
whole-word spellings exempted. Selected Cyrillic/Arabic s-endings, Thai ส,
and Korean 스 get positive levels. Carriage returns and thinking/tool tags
have fixed levels. Everything else is near zero.

Only the immediately previous token in the same document is inspected;
this is a local spelling approximation, not a word or morphology parser.
"""
import unicodedata

READS = ()
VOWELS = frozenset('aeiouyаеиоуыэюяё')
# Ending: baseline, penalty for a vowel-bearing preceding fragment,
# penalty for a preceding fragment longer than two letters.
VOWEL_S = {
    'as': (0.40, -0.66, -0.48),
    'os': (0.19, -0.54, -0.15),
    'es': (0.44, -0.44, -0.25),
    'is': (0.08, -0.31, -0.06),
    'us': (0.30, -0.29, -0.02),
}
DELIMITERS = {
    '\r': 0.68, '<think>': 0.09, '</think>': 0.09,
    '<tool_call>': 0.16, '<tool_response>': -0.15,
}
FUNCTION_WORDS = frozenset(('has', 'was', 'this', 'thus', 'his', 'its', 'yes'))


def predict_piece(token, previous):
    if token in DELIMITERS:
        return DELIMITERS[token]
    if not token.isalpha():
        return 0.002
    i = len(previous)
    while i and previous[i - 1].isalpha():
        i -= 1
    stem = previous[i:]
    plain = unicodedata.normalize('NFD', stem.lower())
    has_vowel = any(c in VOWELS for c in plain)
    lower = token.lower()
    if token.isascii() and lower.endswith('s'):
        if len(token) == 1:
            if not stem:
                return 0.05 if token.isupper() else -0.01
            return -0.23 if len(stem) <= 3 else -0.07
        if lower in VOWEL_S:
            if not (token.islower() or token.isupper()):
                return -0.18 if stem else -0.01
            base, vowel_penalty, length_penalty = VOWEL_S[lower]
            value = base + vowel_penalty * has_vowel
            value += length_penalty * float(len(stem) > 2)
            if token.isupper():
                value += 0.50 if lower == 'es' else 0.10
            return value
        if len(token) == 2 and token[0].isupper() and token[-1] == 's':
            return -0.45
        if not token.islower() or len(token) > 6 or lower in FUNCTION_WORDS:
            return 0.002
        if lower.endswith('ss'):
            return 0.08
        if lower.endswith(('ers', 'ors')):
            return 0.0
        if lower in ('ias', 'ios'):
            return -0.8 if lower == 'ias' else -0.5
        if lower in ('ans', 'ens', 'ins', 'ns'):
            value = -0.4 if lower == 'ens' else -0.32
        elif lower.endswith(('ns', 'ms')):
            value = 0.03 if lower.endswith('ions') else -0.08
        else:
            value = {'as': -0.45, 'os': -0.33, 'is': -0.18, 'us': -0.04}.get(
                lower[-2:], -0.21 if len(token) == 2 else -0.04)
            if lower.endswith('es'):
                value = -0.19 if len(token) <= 4 else -0.1
        return value if stem else value * 0.3
    if lower.endswith('с'):
        base, penalty = {'ес': (0.72, -0.4), 'ос': (0.65, -0.52),
                         'ас': (0.5, -0.15)}.get(lower[-2:], (0.14, -0.08))
        return base + penalty * has_vowel
    if token.endswith('س'):
        return 0.8 if token.endswith('اس') else 0.5
    if token == 'ส':
        return 0.38
    if token == '스':
        return 0.20
    return 0.002


def step(carry, prefix, upstream):
    previous = ''
    if (len(prefix.token_ids) > 1 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    return None, float(predict_piece(prefix.token_strings[-1], previous))

