programs.sol:
"""Approximate bar notation and locally qualified quantities/alternatives.

Vertical bars give positive activations, weakened by nearby repetition
and newlines. Negations and quantifiers give negative activations
on quantity or alternative continuations, especially 'no more', 'at least
one', and 'any other'. A few related phrase endings are handled explicitly.
Other tokens give zero; weak lexical responses are intentionally omitted.
"""
import math

READS = ()
CONTINUATIONS = {
    'more': 1.8, 'one': 1.4, 'other': 1.2, 'once': 1.1,
    'longer': 1.0, 'further': 1.0, 'less': 0.85, 'single': 0.8,
    'two': 0.7, 'three': 0.5,
}
QUALIFIERS = {
    'no': 1.0, 'nothing': 0.75, 'anything': 0.7,
    'every': 0.65, 'any': 0.6, 'not': 0.6, 'without': 0.6,
    'some': 0.4, 'only': 0.4, 'just': 0.38, 'each': 0.38,
    'even': 0.35, 'little': 0.35, 'few': 0.35,
    'or': 0.4, 'much': 0.2, 'exactly': 0.23, 'a': 0.18,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, bars = ((), 0.0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = history[-1] if history else ''
    single_bar = '|' in token and '<|' not in token and '||' not in token
    value = 0.0
    if single_bar:
        value = 1.16 + 0.14 * token.startswith(' ')
        value -= 0.90 * bars / (2 + bars) + 0.54 * ('\n' in token)
        value = max(0.0, value)
    elif '||' in token and '<|' not in token:
        value = 0.65 + 0.15 * token.startswith(' ') - 0.2 * ('\n' in token)
    elif '&&' in token:
        value = 0.36 - 0.12 * ('\n' in token)
    elif word in ('│', '∣'):
        value = 0.45
    elif word in ('mid', 'vert') and previous.endswith('\\'):
        value = 0.9 if token == 'Vert' else 0.65
    elif word in CONTINUATIONS:
        strength = QUALIFIERS.get(previous, 0.0)
        if word == 'more' and previous == 'or':
            if any(w in ('one', 'two', 'three') for w in history[-4:]):
                strength = 0.95
        elif word == 'more' and previous in ('one', 'once', 'two'):
            strength = {'one': 0.5, 'once': 0.65, 'two': 0.26}[previous]
        elif word in ('one', 'once', 'two') and previous in ('least', 'than'):
            strength = 0.75 if previous == 'least' else 0.55
            if word == 'two':
                strength *= 0.5
        elif word == 'other':
            strength = {'each': 0.33, 'all': 0.47, 'or': 0.25,
                        'any': 0.68, 'some': 0.50}.get(previous, strength)
            if previous == 'the' and 'one' in history:
                strength = 0.27
        value = -CONTINUATIONS[word] * strength
    elif word == 'than':
        value = -0.83 if previous == 'more' else -0.15
    elif word == 'if':
        value = {'else': -0.69, 'even': -0.31, 'or': -0.24}.get(previous, 0.0)
    elif word == 'else':
        value = -0.10
        if previous != 'none' and previous.endswith(('thing', 'one', 'body', 'where')):
            value = -1.1 if previous.startswith('any') else -0.88
    elif word == 'another' and 'one' in history:
        value = -1.1
    elif word == 'or' and previous in ('one', 'more', 'whether'):
        value = -0.35
    elif word == 'again' and previous == 'once':
        value = -0.48
    bars = (bars + single_bar) * math.exp(-1 / 24)
    return (doc, (history + (word,))[-6:], bars), float(value)

