    elif word == "one" and previous in {"least", "exactly", "no"}:
        value = -0.9
    elif word == "other" and previous in {"the", "each", "any"}:
        value = -0.45
    elif word == "if" and previous == "else":
        value = -0.7
    elif word == "than" and previous in {"more", "later"}:
