programs.sol:
"""Approximate a local spelling-transition signal, strongest after an o-ending piece.
Joined i/j/y-like continuations are positive; several b/p clusters are negative.
Related Cyrillic and Greek letters, scientific combining forms, length and case
refine the score. Weaker versions follow a/u/e. Across whitespace, use a handful
of common function-word constructions instead: notably 'do I/you/we' and 'so
that'. 'How do ...' gets an extra boost, strongest early in the document.

This models salient local transitions, not the diffuse word-specific background.
Only the previous two tokens and document position are carried across calls.
"""
import unicodedata

READS = ()
DO_SUBJECT_BASE = {'i': 1.5, 'you': 1.4, 'we': 1.1}
HOW_DO_BONUS = {'i': 1.1, 'you': 1.6, 'we': 1.4}
SO_NEXT = {'that': 0.83, 'i': 0.72, 'we': 0.35, 'you': 0.30,
           'as': -0.68, 'far': -0.59, 'the': -0.21, 'it': -0.30, 'if': -0.35}


def base_letter(char):
    return unicodedata.normalize('NFD', char.lower())[:1]


def joined(previous, token):
    if not previous or not token or token[0].isspace():
        return 0.0
    ending = base_letter(previous[-1])
    # The three o's below are Latin, Greek, and Cyrillic.
    strength = {'o': 1.0, 'ο': 1.0, 'о': 1.0,
                'a': 0.24, 'u': 0.15, 'e': 0.04}.get(ending, 0.0)
    if len(previous.strip()) > 3 and ending in {'o', 'ο', 'о'}:
        strength *= 0.73
    if not strength:
        return 0.0
    text = token.lower()
    first = base_letter(text[0])
    size = len(text)
    if first in 'ijy':
        score = 1.5
        if first == 'i' and size > 1:
            if text.startswith(('is', 'ie', 'ic', 'iv', 'it')):
                score += 0.3
            if text.startswith(('il', 'in')):
                score -= 0.4
        if text.startswith('ich'):
            score = 2.5
        elif size > 3:
            score *= 0.65 if size < 6 else 0.35
    elif first in 'ийіїяю':  # Cyrillic i-like and iotated vowels.
        score = 1.7 if first in 'ийії' else 1.3
        if size > 5:
            score *= 0.55
    elif text[0] == 'ë':
        score = 1.3
    elif first == 'ι':
        score = 2.3
        if text[0] == 'ί':
            score = 3.3
    elif first == 'υ':
        score = 1.2
    elif first == 'b':
        score = -0.5
        if text.startswith('bs'):
            score = -1.9
        elif text.startswith('ber'):
            score = -1.1
        elif size > 3:
            score *= 0.3
    elif first == 'p':
        score = -0.6
        if text.startswith('pt'):
            score = -2.5 if size <= 3 else -1.6
        elif size > 3:
            score *= 0.5
    elif first in 'aeofrv':
        score = -0.35 if size < 5 else -0.09
    elif text.startswith(('log', 'graph', 'gram', 'scop', 'static', 'chem')):
        score = 0.8
    elif first in 'glxλ':
        score = 0.25
    elif text.startswith(('ct', 'ce')):
        score = -0.4
    elif token[0].isdigit():
        score = 0.3
    else:
        score = 0.025
    if size > 2 and token.istitle():
        score *= 0.2
    return strength * score


def step(carry, prefix, upstream):
