    (PRONOUNS, 0.05, 0.15, 0.35),
    (AUXILIARIES, 0.02, 0.42, 0.51),
    (ADVERBS, 0.12, 0.46, 0.54),
    (NUMERALS, 0.0, 0.53, 0.93),
    (SIZE_QUALITY, 0.03, 0.73, 0.94),
    (PARTICLES, 0.13, 0.21, 0.35),
    (NOMINAL_SUFFIXES, 0.02, 0.57, 0.63),
    (CLASSIFIERS, 0.075, 0.23, 0.25),
