            value = -0.06
        elif prev_kind == 'kana_character':
            value = 0.15
        else:
            value = 0.0 if prev_kind == 'han_character' else -0.04
    elif kind == 'kana_word':
        value = -0.10 if prev_kind == 'han_character' else -0.04
    elif kind == 'byte_fragment':
