READS = ()
# Character: (settled response, extra response near document start).
PUNCTUATION = {
    '。': (1.35, 1.80),
    '？': (0.29, 0.66),
    '！': (0.46, 0.92),
    '；': (0.52, 0.61),
    '：': (0.02, 1.04),
    '，': (-0.18, 0.50),
    '（': (-0.24, 0.17),
    '）': (0.18, 0.68),
    '、': (-0.11, 0.25),
}


def script_counts(s):
    return (sum('\u4e00' <= c <= '\u9fff' for c in s),
            sum(c.isalpha() and '\u3040' <= c <= '\u30ff' for c in s),
            sum(c.isalpha() for c in s))


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, [0, 0, 0])
    _, position, counts = carry
    han, kana = (counts[i] / max(1, counts[2]) for i in (0, 1))
    early = (1 + position / 20) ** -0.8
    initial = 2 ** (-position / 3.5)
    value = 0.0
    if s == '<|endoftext|>':
        value = 1.29 + 0.96*han + 0.29*kana + 0.30*early - 0.20*initial
    else:
