                    base, boost = 0.44, 1.90
                elif s.endswith('”'):
                    base, boost = 0.97, 1.35
                elif s.endswith('“'):
                    base, boost = 1.14, 0.90
                elif s.endswith(('「', '<', '\\')):
                    base, boost = 0.70, 0.20
            elif mark == '，':
