            elif mark in '？！' and '”' in s:
                base += 0.25
                boost -= 0.15
            elif mark == '？' and '\n' in s:
                base += 0.10
                boost += 0.24
            value = strength * (base + boost*early + extra)
        elif s in {'“', '”', '「', '」', '『', '』'}:
            value = 0.05*han - 0.04*kana + 0.30*early + 0.48*initial
        elif '……' in s:
            value = 0.35 + 0.25*early
        elif '\n' in s:
            value = 0.20*han + 0.05*kana + (0.07 + 0.85*han)*early
            if s != '\n':
                value *= 0.6
            value += 0.25*initial
