        if s.isspace() and '\n' in s:
            value = 0.71 if s == '\n' else 0.79
        elif s == '。':
            value = 2.45
        elif s == '<|endoftext|>':
            value = 1.01
    new = script_counts(s)
    for i in range(3):
        counts[i] += new[i]
    return (doc, position + 1, counts), float(value)

