"""Approximate the formatting response from the current whitespace token.

Four-space multiples are the strongest negative signal. For these blocks,
a previous newline and early document position strengthen the response;
a space before the preceding newline softens it. Tabs and space-padded
blank lines have separate width-based responses. Ordinary text is predicted
as zero, omitting smaller lexical responses. Width is token-local, not the
total indentation of a line.
"""
import math

READS = ()


def whitespace_response(s, previous="", position=1000):
    after_newline = previous.endswith("\n")
    first = position == 0
    if s and not s.strip(' '):
        n = len(s)
        if n == 1:
            return 0.09 if after_newline else 0.0
        if n == 2:
            return -0.02 if after_newline else 0.10
        if n >= 64:
            return -1.7 if n < 100 else -0.6
        if n % 4 == 0:
            if first:
                return -5.5 if n == 4 else -4.6
            value = -2.66 - (0.15 if n == 4 else 0.0)
            value -= 0.50 if n >= 24 else 0.0
            value -= 0.79 if after_newline else 0.0
            value += 0.32 if previous.endswith(" \n") else 0.0
            return value - 1.24 * math.exp(-position / 32)
        if n % 4 == 2:
            return -0.78 - 0.035 * n - (0.18 if after_newline else 0.0)
        return 0.06 - min(1.4, 0.05 * max(n - 16, 0))

    if s and not s.strip('\t'):
        n = len(s)
        if n == 2:
            return -0.12
        return 0.05 - min(1.55, 0.32 * max(n - 3, 0))

    if s.startswith('\t') and not s.strip('\t '):
        n = s.count(' ')
        if n % 4 == 0:
            value = -2.5 - 0.025 * n
        elif n == 1:
            value = 0.12
        elif n % 4 == 1:
            value = -0.35 - 0.035 * n
        elif n % 4 == 2:
            value = -0.95
        else:
            value = -0.4 - 0.05 * n
            if n == 7:
                value -= 0.34
        return value - (0.25 if after_newline else 0.0)

    if '\n' in s and not s.strip(' \r\n'):
        n = len(s) - len(s.lstrip(' '))
        if n <= 1:
            return 0.0
        if n == 2:
            return 0.15
        if n == 3:
            return -0.08
        if n % 4 == 0:
            return -0.65 - 0.02 * n
        if n % 4 == 1:
            return -1.2 - 0.01 * n
        return -0.4 - 0.015 * n
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous = 0, ""
    else:
        position, previous = carry[1], carry[2]
    token = prefix.token_strings[-1]
    value = whitespace_response(token, previous, position)
    return (document, position + 1, token), float(value)

