HIRA_E = 'えけせてねへめれぇ'
KANA_I = 'イキシチニヒミリィいきしちにひみりぃ'
KANA_R = 'ラリルレロらりるれろ'
VOWEL_GROUPS = (
    ('еэє', 2.20),                 # Cyrillic e vowels
    ('€', 1.50),                   # E-shaped sign
    (KATA_E, 1.50), (HIRA_E, 0.80),
    (KANA_I + 'iyиы', 0.25),
    ('aαяа', 0.24), ('oοωо', 0.14), ('uуυ', 0.12),
    ('æəъ', 1.39),                 # ae and reduced vowels
)
LIQUID_GROUPS = (
    ('l', 0.42), ('r', 1.01),
    ('ρ', 2.13), ('λ', 0.97),       # Greek rho/lambda
    ('р', 0.90), ('л', 0.36),       # Cyrillic r/l
)


def unaccent(s):
    s = ''.join(c for c in ud.normalize('NFD', s).lower()
                if not ud.combining(c))
