def hangul(s):
    return bool(s) and '\uac00' <= s <= '\ud7a3'


@lru_cache(maxsize=8192)
def vowel_strength(token):
    s = token.strip()
    original = s[-1:]
    c = unaccent(original)
    if not c:
        return 0.0
    k = next((k for letters, k in VOWEL_GROUPS if c in letters), 0.0)
    if c == 'e':
        k = 2.05 if original.lower() == 'e' else 1.75
    elif c in 'εη':
        accented = '\u0301' in ud.normalize('NFD', original)
        if c == 'ε':
            k = 1.43 if accented else 1.12
        else:
            k = 0.78 if accented else 0.60
        marks = ud.normalize('NFD', original)
        if '\u0313' in marks or '\u0314' in marks:
            k *= 0.40  # Ancient Greek breathing marks.
        if original.isupper():
            k *= 0.25
