        n = ord(original) - 0xac00
        # Open Hangul syllable with vowel ae, yae, e or ye.
        e_vowel = (n // 28) % 21 in (1, 3, 5, 7)
        k = 1.30 if n % 28 == 0 and e_vowel else 0.0
    elif s.startswith('เ'):
        k = 1.0  # Thai preposed e-like vowel.
    k *= math.exp(-0.25 * max(len(s) - 2, 0))
    return k * (0.93 if token[:1].isspace() else 1.0)


@lru_cache(maxsize=8192)
def liquid_strength(token):
    s = unaccent(token.lstrip(' -._/'))
    c = s[:1]
    if not c:
        return 0.0
    k = next((k for letters, k in LIQUID_GROUPS if c in letters), 0.0)
    syllabic = c in KANA_R or c == 'ร'
    if syllabic:
        k = 1.0
    elif hangul(c):
        n = ord(c) - 0xac00
        k = 1.0 if n // 588 == 5 and n % 28 == 0 else 0.0
        syllabic = True  # Open syllable beginning with rieul.
    elif s in ('le', 'les'):
        k = 1.0
    else:
