    value = -vowel_strength(previous) * liquid_strength(token)
    if unaccent(previous[-1:]) == 'e' and token.startswith('^'):
        value = .82 if token == '^' else .43
    if previous == '3' and token.strip() in ('r', 'rd'):
        value = -.57
