    "acid", "ase", "anol", "ethylene", "iodide", "nitride", "oxide",
    "chloride", "fluoride", "hydroxide", "sulfide", "bromide", "particle",
)
BIO_MEDICAL = (
    "oma", "otic", "arthritis", "carcinoma", "peritone", "idae",
    "lysate", "defensin", "sitagliptin",
)


def _ending(text):
    i = len(text)
    while i and text[i - 1].isalpha():
        i -= 1
    return text[i:]


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    old_doc, old_word, old_pieces = carry or (doc, "", 0)
    if doc != old_doc:
        old_word, old_pieces = "", 0

    if token.isalpha() and old_word:
        word, pieces = old_word + token, old_pieces + 1
    else:
        word = _ending(token)
        pieces = 1 if word else 0

    low = word.lower()
    score = 0.0
    chemical = any(low.endswith(s) for s in CHEMICAL)
    bio_medical = any(low.endswith(s) for s in BIO_MEDICAL)
    if chemical and len(word) >= 4:
        score = -1.3
    elif bio_medical and len(word) >= 5:
        score = -1.3
    elif len(word) >= 7 and pieces >= 2 and low.endswith(("ene", "ane", "in")):
        score = -0.8
    elif len(word) >= 7 and pieces >= 2 and low.endswith(("us", "is")):
        score = -0.55
    elif low.endswith("酸"):
        score = -1.3

    if token and not token[-1].isalpha():
        word, pieces = "", 0
    return (doc, word, pieces), score * 0.5

