"""Approximate an English 'by' detector with local wording effects.

On the token ' by', containment, physical impact, and ownership words
predict especially large responses. Other '-ed' words predict a moderate
response. Supplying, hosting, and ordering words instead predict a small
negative response. Arithmetic, divisibility, and conjunctions have their
own levels. Other spellings of 'by' and 'via' get weaker fixed responses;
all remaining tokens get zero. Keep only recent text, resetting at each
new document. This captures the salient 'by' signal, not the numerous
small, idiosyncratic responses elsewhere.
"""
import re

READS = ()

CONTAINMENT = set('''
    surrounded enclosed bounded covered occupied wrapped blocked encircled
'''.split())
PHYSICAL_IMPACT = set('''
    affected damaged destroyed hit struck killed attacked shocked injured
    wounded captured frightened feared
'''.split())
OWNERSHIP = {'owned', 'held', 'possessed'}
FORMATION_AND_CONTROL = set('''
    obtained used required formed made controlled influenced spanned subtended
'''.split())
SUPPLYING = {'given', 'provided', 'supplied', 'offered', 'furnished', 'distributed'}
HOSTING = {'powered', 'hosted', 'sponsored', 'presented'}
ORDERING = {'sort', 'order', 'group'}
ARITHMETIC = {'divide', 'divided', 'multiplied', 'multiply', 'dividing'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ' by':
        match = re.search(r'([A-Za-z]+)\s*$', tail)
        word = match[1].lower() if match else ''
        if word in CONTAINMENT:
            value = 2.36
        elif word in PHYSICAL_IMPACT or word in OWNERSHIP:
            value = 1.8
        elif word in FORMATION_AND_CONTROL or word in {'seen', 'followed'}:
            value = 1.55
        elif word in SUPPLYING or word in HOSTING or word in ORDERING:
            value = -0.2
        elif word in ARITHMETIC or word in {'and', 'or'}:
            value = 0.35
        elif word == 'divisible':
            value = 1.25
        elif word.endswith('ed'):
            value = 1.0
        else:
            value = 0.61
    elif token in {'by', 'By', '(by', '(By'}:
        value = 0.54
    elif token in {' By', ' BY', 'BY'}:
        match = re.search(r'([A-Za-z]+)\s*$', tail)
        word = match[1].lower() if match else ''
        value = -0.2 if word in ORDERING else 0.38
    elif token in {'-by', '_by'}:
        value = 0.8
    elif token in {'/by', '.by'}:
        value = 0.38
    elif token == ' via':
        value = 0.2
    return (doc, (tail + token)[-80:]), value

