"""layers.0.mlp.down_proj:4768 is a detector for the word "by".

It fires on the standalone word "by" in any capitalisation ("by", " by", " By",
" BY"). Its size depends on the word just before it:
- after a past participle (a word ending in "-ed": "followed by", "surrounded by",
  "obtained by", "captured by") it is strongest, about 1.0 (the agent of a passive);
- after a credit verb ("provided by", "powered by", "given by", "sponsored by")
  it is slightly negative, -0.3;
- any other "by" ("step by step", "close by", "multiplied by", "by the way") is
  about 0.6.
Every other token gives 0. Words that only contain "by" (ruby, bytes, baby) give 0.
"""

READS = ()

BY_WORDS = {" by", "by", " By", "By", " BY"}
CREDIT_VERBS = {"provided", "given", "presented", "sponsored", "powered", "sorted",
                "supplied", "offered"}


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] not in BY_WORDS:
        return None, 0.0
    before = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2].strip().lower()
    if before in CREDIT_VERBS:
        return None, -0.3
    if before.endswith("ed"):
        return None, 1.0
    return None, 0.6

