"""Detect ` by`, with a stronger response after participial verb forms."""
READS = ()

IRREGULAR_PARTICIPLES = {
    "been", "born", "bound", "built", "bought", "caught", "chosen",
    "done", "drawn", "driven", "eaten", "felt", "found", "given",
    "gone", "held", "known", "left", "lost", "made", "paid", "read",
    "seen", "sent", "shown", "spoken", "taken", "told", "won",
    "written", "brought", "thought", "foretold", "overseen",
}

def is_participle(word):
    return word.endswith("ed") or word.endswith("en") or word in IRREGULAR_PARTICIPLES

def step(carry, prefix, upstream):
    """Use a rolling word history; favor ` by` after participle-like words."""
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        open_word, recent = "", ()
    else:
        open_word, recent = carry[1], carry[2]

    token = prefix.token_strings[-1]
    before = (recent + ((open_word,) if open_word else ()))
    participle_nearby = any(is_participle(word) for word in before[-2:])
