    if token == " by":
        value = 1.15 if participle_nearby else 0.55

    words = list(recent)
    for char in token:
        if char.isalnum():
            open_word += char.lower()
        elif open_word:
            words.append(open_word)
            words = words[-3:]
            open_word = ""
