I_VARIANTS = {
    '이': -1.8, 'イ': -1.75, 'ı': -0.9, 'î': -0.85,
    'ï': -0.85, 'í': -0.2, 'і': -0.3, 'ї': -0.55,
    'й': -0.4, 'Й': -0.6, 'υ': -0.5, 'ύ': -0.4,
    'І': -0.7, 'İ': -0.7, 'ī': -0.55, 'ی': -0.1, 'ي': -0.2,
}
SPLIT_I_VOWELS = {
    'ι': -5.8, 'Ι': -5.7, 'ί': -4.1, 'И': -1.2,
    'І': -2.5, 'ї': -3.0, 'і': -1.2, 'Й': -1.5,
    'イ': -4.1, 'シ': -2.2, 'υ': -1.1, 'ִ': -1.6,
}
AUXILIARIES = set('do does did can could shall should will would may must'.split())
CONDITIONALS = set('if when whenever before until maybe perhaps'.split())

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    # A byte-fragment token can finish a character begun by the prior token.
    if '\ufffd' in token:
        end = prefix.text_prefixes[-1][-1:]
        value = SPLIT_I_VOWELS.get(end, 0.0)
        base = unicodedata.normalize('NFD', end)[:1]
        if base in {'ι', 'Ι'} and end not in SPLIT_I_VOWELS:
            value = -2.0
        return (doc, token), value
    letters = ''.join(c for c in token if c.isalpha())
    last = previous[-1:] if previous else ''
    word = previous.strip().lower()
    value = 0.0
    if letters in {'ι', 'ί', 'Ι'}:
        # Iota following another vowel often belongs to a Greek vowel pair.
        if last == '\ufffd' and prefix.position:
            last = prefix.text_prefixes[-2][-1:]
        base = unicodedata.normalize('NFD', last)[:1].lower()
        if base in {'ε', 'ο'}:
            value = -3.0
        elif base == 'α':
            value = -3.3
        elif not base.isalpha():
            value = -4.8
        else:
            value = -7.1
    elif len(letters) == 1 and unicodedata.normalize('NFD', letters)[:1] == 'ι':
        value = -2.8
    elif letters == 'αι':
        value = -1.4
    elif letters in {'I', 'i', 'И', 'и'}:
        attached = token == letters and last.isalpha()
        if attached:
            value = -0.3 if last.isupper() else -0.95
            if letters in {'i', 'и'}:
                value = -0.25 if last.islower() else -0.65
            if letters == 'И':
                value = -0.9
        elif letters == 'I':
            value = -1.05
            if token[:1].isspace():
                if word in AUXILIARIES:
                    value = -0.15
                elif word in CONDITIONALS:
                    value = -0.5
                elif last in '.!?':
                    value = -1.25
                else:
                    value = -0.95
        elif letters == 'i':
            value = -0.83
            if token == 'i' and last in '({[+-':
                value = -0.96
            if token.startswith('['):
                value = -0.55
        else:
            value = -1.0
    elif letters in I_VARIANTS:
        value = I_VARIANTS[letters]
    elif token.strip() == 'ِ':  # Arabic short i vowel (kasra).
        value = -2.6
    return (doc, token), value

