_EDGE_PUNCTUATION = " \t\n.,;:!?()[]{}'\"`*_=-"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    core = token.strip().strip(_EDGE_PUNCTUATION)

    if len(core) == 1:
        name = unicodedata.name(core, "")
        if "IOTA" in name:
            if core.isupper():
                return None, -1.0
            if "PSILI" in name:
                return None, -2.5
            return None, -5.0
        if name == "HANGUL SYLLABLE I":
            return None, -1.8
        if name == "KATAKANA LETTER I":
            return None, -2.3
        if name.endswith(" LETTER I"):
            if core.isupper():
