"""A detector for the spelling pair ``ud``, strongest on short word pieces.

Letters surrounding the pair weaken it. Some common longer word families
(student, include, cloud) barely respond; judging, auditing and studio words
retain a stronger response. The Cyrillic pair уд and Arabic fragment ود receive
smaller positive predictions. PD/PDF have a small positive response too. These are
spelling rules, not judgments about the topic.
"""
READS = ()


def spelling(token):
    text = token.strip()
    s = text.lower()
    j = s.find('ud')
    if j >= 0:
        left, right = s[:j], s[j + 2:]
        if any(part in s for part in ('clud', 'cloud', 'student', 'sudden')):
            return 0.0
        if any(part in s for part in ('study', 'studies', 'studied')):
            return 0.8 if 'studying' in s else 0.3
        if 'studio' in s:
            return 2.3 if not s.endswith('s') else 1.9
        if 'audit' in s:
            return 0.8 if s.endswith('ory') else 3.0
        if not left:
            if not right:
                if text == 'Ud':
                    return 2.1
                if token.startswith(' '):
                    return 3.75
                return 5.2 if text.isupper() else 4.7
            if right.startswith('g'):
                return 4.4
            if right == 's':
                return 4.1
            tail = right
            if right.endswith('s') and right[0] in 'ao':
                tail = right[:-1]
            value = max(0.0, 3.5 - 0.65 * len(tail))
            if right in ('er', 'es', 'ed'):
                value = 1.4
        elif not right:
            value = max(0.0, 4.4 - 0.9 * len(left))
            if len(left) == 2:
                value = 0.9 if any(c in 'aeiou' for c in left) else 3.3
            if left.endswith('o'):
                value -= 0.9
            if text.isupper() or text.istitle():
                value += 0.6 if len(left) == 1 else 0.0
        else:
            value = 3.5 / (1.0 + 0.8 * len(left) + 0.45 * len(right))
            if 'judg' in s:
                value += 0.8 if len(s) <= 6 else -0.1
            if 'itude' in s:
                value *= 0.25
        return max(0.0, value)
    if 'уд' in s:
        left, right = s.split('уд', 1)
        if not left and not right:
            return 1.1 if token.startswith(' ') else 3.8
        if not right:
            return 2.2 if len(left) == 1 else 0.5
        return 0.4 if len(s) <= 5 else 0.0
    if s == 'ود':
        return 1.5
    if s in ('pd', 'pdf'):
        return 1.4 if s == 'pd' else 1.1
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = spelling(token)
    # Bare 'ud' is weaker after a lowercase vowel, stronger after a capital.
    if token == 'ud' and len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2][-1:]
            if previous and previous in 'aeiou':
                value -= 0.8
            elif previous.isupper():
                value += 0.6
    return None, float(value)

