COPULAS = set('is are was were be been being'.split())
CONJUNCTIONS = set('and or but nor'.split())
APPROXIMATIONS = set('about around approximately roughly nearly almost than'.split())
MONTHS = set('january february march april may june july august september october '
             'november december jan feb mar apr jun jul aug sep sept oct '
             'nov dec'.split())


def space_response(previous):
    if previous is None:
        return 0.14
    if '\n' in previous and previous[-1].isspace():
        return -0.09
    if previous.isspace():
        if '\xa0' in previous:
            return 0.88
        n = len(previous)
        if n == 1:
            return 0.35
        if n == 2:
            return 0.45
        return min(0.90, 0.64 + 0.09 * math.log2(n / 3))

    word = previous.strip().lower()
    if word in DETERMINERS:
        return 2.03
    if word in PREPOSITIONS:
        return 1.86
    if word in COPULAS:
        return 1.62
    if word in CONJUNCTIONS or word in MONTHS or word in APPROXIMATIONS:
        return 1.68
    if previous == '\\n':
        return 0.90

    last = previous.rstrip()[-1]
    if last.isdecimal():
        return 0.95
    if last.isalpha():
        return 1.38 if last.isascii() else 1.45
    if last in '.!?。！？':
        return 0.15
    if last in ',:，：':
        return 0.99
    if last in ';)]}':
        return 0.80
    if last in '=+-*/<>−–—×÷':
        return 1.44 if previous[0].isspace() else 0.82
    if last in '([{':
        return 1.25
    return 1.0


def writing_script(token):
    for char in reversed(token):
        if char.isascii():
            continue
        name = unicodedata.name(char, '')
        if any(script in name for script in (
            'DEVANAGARI', 'BENGALI', 'GURMUKHI', 'GUJARATI', 'ORIYA',
            'TAMIL', 'TELUGU', 'KANNADA', 'MALAYALAM', 'SINHALA')):
            return 'indic'
        if any(script in name for script in (
            'CJK', 'HIRAGANA', 'KATAKANA', 'HANGUL')):
            return 'east_asian'
        if 'GREEK' in name:
            return 'greek'
        if 'CYRILLIC' in name:
            return 'cyrillic'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, script, age = 0, None, None, 0
    else:
        _, position, previous, script, age = carry
        position += 1
        age += 1
    token = prefix.token_strings[-1]
    if token == ' ':
        value = space_response(previous)
        if position:
            value *= max(0.75, 1.47 - 0.065 * math.log2(position + 1))
    elif token == ' \ufffd':
        if age > 25:
            script = None
        value = {'indic': 3.9, 'east_asian': 0.3,
                 'greek': 2.0, 'cyrillic': 1.1}.get(script, 1.1)
    else:
        value = 0.0
    newest_script = writing_script(token)
    if newest_script:
        script, age = newest_script, 0
    return (doc, position, token, script, age), value

