"""A local phrase-and-format approximation, not a single semantic detector.

Positive on "of" after measurement/type nouns; negative after composition
verbs or institutional titles. Also distinguishes a few infinitival and
prepositional relations, grammatical word classes, and protocol delimiters.
Unlisted vocabulary gets a small near-zero baseline: most lexical variation
is not explained. Context is just the previous token, reset per document.
"""

READS = ()

MARKERS = {
    '<|endoftext|>': -0.019,
    '<|im_start|>': -0.027,
    '<|im_end|>': 0.085,
    '<think>': -0.119,
    '</think>': -0.038,
    '<tool_call>': -0.044,
    '</tool_call>': 0.004,
    '<tool_response>': 0.052,
    '</tool_response>': -0.152,
}

# Closed grammatical classes: quantification, restriction, and modal force.
GRAMMAR = (
    ('all each every', 0.025),
    ('any some', -0.034),
    ('both neither', -0.033),
    ('more most enough', 0.034),
    ('only just', -0.026),
    ('own', -0.044),
    ('will shall should must', 0.027),
    ('would might', -0.013),
)
WORD_LEVELS = {w: level for words, level in GRAMMAR for w in words.split()}

# Preposition -> (semantic class of the preceding word, expected activation).
PHRASES = {
    'of': (
        # Magnitude, classification/process, and parts/locations.
        ('amount level levels degree extent intensity', 0.116),
        ('type types form forms nature process method stage purpose', 0.110),
        ('part parts place rest end time effect effects', 0.056),
        # Composition, institutions, and education.
        ('consist consists consisted consisting composed comprised', -0.135),
        ('ministry department institute board republic faculty academy', -0.105),
        ('university college school', -0.034),
        ('all most', 0.075),
    ),
    'to': (
        # Capacity/difficulty, limiting/comparing, attempts, attribution.
        ('ability access failure failed hard easy difficult required important', 0.063),
        ('limited adjacent similar prior respect order', -0.095),
        ('try tries tried trying', -0.047),
        ('according due', 0.045),
    ),
    'with': (
        ('associated association deal dealing patients problem', -0.091),
        ('finished completed along contact', 0.042),
    ),
    'in': (
        ('result results resulted change changes election', 0.039),
        ('found located built stored published involved', -0.040),
    ),
    'on': (
        ('depend depends depending dependent rely', -0.021),
        ('effect impact focused focuses', 0.037),
    ),
}
PHRASE_LEVELS = {(previous, word): level
                 for word, groups in PHRASES.items()
                 for words, level in groups for previous in words.split()}


def token_level(s):
    if s in MARKERS:
        return MARKERS[s]
    w = s.strip()
    if w.isascii() and w.isalpha():
        if w.lower() in WORD_LEVELS:
            return WORD_LEVELS[w.lower()]
        if not s[0].isspace():
            if w in {'er', 'est'}:
                return 0.044
            if w in {'al', 'ous', 'ive', 'able', 'ible'}:
                return 0.030
        if len(w) == 1:
            return -0.004
        if w.isupper():
            return -0.006
        if w[0].isupper():
            return 0.006
    if w.startswith('\\x'):
        return 0.037
    if w == '_':
        return 0.030
    if w == '**':
        return -0.038
    if w == '|' and not s[0].isspace():
        return -0.036
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    word = s.strip().lower()
    value = token_level(s)
    if s[:1].isspace():
        value = PHRASE_LEVELS.get((previous, word), value)
    if s == '<|im_end|>':
        if previous == '</tool_response>':
            value = -0.009
        elif previous == '</tool_call>':
            value = 0.013
    return (doc, word), float(value)

