"""Near-dead MLP down-projection component layers.0.mlp.down_proj:4776.

Its activation is small (RMS 0.03) and has no clear concept behind it: its variance
is only weakly tied to the current token's kind. The simple reading kept here: it is
slightly positive on alphabetic word pieces and on CJK / non-ASCII text, and near zero
on punctuation, digits and whitespace. The program predicts those class means.
"""

READS = ()

WORD_MEAN = 0.003     # letter-only pieces (with or without a leading space)
CJK_MEAN = 0.005      # CJK ideographs, kana, other non-ASCII text
OTHER_MEAN = 0.0      # punctuation, digits, whitespace, mixed code tokens


def _is_cjk(s):
    return any(ord(ch) > 0x2E80 for ch in s)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    core = s.strip()
    if not core or "�" in s:
        value = OTHER_MEAN
    elif _is_cjk(core):
        value = CJK_MEAN
    elif core.isalpha():
        value = WORD_MEAN
    else:
        value = OTHER_MEAN
    return carry, float(value)

