"""Detect zeroes inside numbers, plus vocabulary expressing tens.

A leading zero is weak; a zero following digits is strong. Decimal and
thousands separators give intermediate responses. Words for teens, tens,
hundreds and decades, and tokens containing Chinese ten, also activate it.
A zero at the first position has a separate boundary response. State tracks
only the previous token and the current digit-run length.
"""
READS = ()
DIGITS = '0123456789'
ZERO_AFTER = (1.36, 1.43, 1.36, 1.74, 1.63,
              1.80, 1.74, 1.82, 1.67, 1.80)
TENS = dict(zip(
    'ten twenty thirty forty fifty sixty seventy eighty ninety'.split(),
    (1.77, 2.0, 1.71, 1.55, 1.43, 1.63, 1.34, 1.07, 1.14)))
TEENS = set('eleven twelve thirteen fourteen fifteen sixteen '
            'seventeen eighteen nineteen'.split())
RELATED = {
    'hundred': 1.1, 'hundreds': 1.0, 'tens': 1.13, 'tenth': 1.3,
    'twentieth': 1.35, 'entieth': 1.35, 'nineteenth': 0.69,
    'decade': 1.08, 'decades': 1.18, 'zero': 0.26,
    'october': 0.8, 'december': 0.45, 'oct': 0.5, 'dec': 0.29,
}


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    _, previous, run = (doc, '', 0) if first else carry
    word = token.strip().lower()
    value = 0.0
    if token == '0':
        if first:
            value = 1.21
        elif len(previous) == 1 and previous in DIGITS:
            value = ZERO_AFTER[int(previous)]
            if run > 1:
                value += (0.3 if previous == '1' else
                          0.2 if previous == '0' else 0.17)
        elif previous.startswith(('\\x', 'x')) and previous[-1:] in 'abcdef':
            value = 0.65  # A zero continuing an escaped/hexadecimal number.
        else:
            value = {'.': 0.76, ',': 0.35, ':': 0.2}.get(previous, -0.08)
    elif word in TENS:
        value = TENS[word] - (0.2 if token.strip()[0].isupper() else 0)
        if token == 'ten':
            value = 0.29  # Usually a fragment inside a longer word.
    elif word in TEENS:
        value = 0.95
    elif word in RELATED:
        value = RELATED[word]
    elif '十' in token:
        value = 4.3 if token == '十' else 2.8 if token.endswith('十') else 1.6
    elif token == '百':
        value = 1.5
    elif token == '０':
        value = 1.5 if previous[-1:].isdigit() else 0.3
    elif '\ufffd' in token and prefix.text_prefixes[-1].endswith('十'):
        value = 5.5  # The current bytes complete the Chinese character ten.
    run = run + 1 if len(token) == 1 and token in DIGITS else 0
    return (doc, token, run), float(value)

