    token = prefix.token_strings[-1]
    before, close, after = token.rpartition(']')
    value = 0.0
    if '】' in token or '］' in token:
        value = 0.45 if token.endswith(('】', '］')) else 0.19
    elif close:
        if '[' in before:
            value = 0.02 - 0.04 * token.startswith(' ') - 0.06 * bool(after)
        elif not after:
            value = 0.56 if not before.strip() else 0.40
            if '\\' in before:
                value = 0.73
        elif after.isspace():
            value = 0.06 - 0.05 * (after.count('\n') > 1) + 0.07 * bool(before)
        else:
            value = SUFFIX_RESPONSE.get(after[0], 0.07)
            if after[0].isalpha():
                value = 0.42
            elif after[0] == '.':
                value += 0.09 * bool(before) - 0.09 * ('\n' in after)
            elif after[0] == ':':
                value -= 0.09 * ('\n' in after)
            elif after[0] == ',':
                value += 0.04 * bool(before)
    return None, float(value)

