READS = ()
FACTORIES = {'new', 'default', 'create', 'make', 'builder', 'init'}
CONVERSIONS = {'from', 'try', 'with', 'to'}
STREAMS = {'cout', 'cerr', 'cin', 'endl', 'ostream', 'iostream'}


def han(s):
    return bool(s) and all('\u3400' <= c <= '\u9fff' for c in s)


def scoped_name(name):
    if name in FACTORIES:
        return 4.3
    if name in CONVERSIONS or name.startswith('get'):
        return 3.4
    if name == 'test':
        return 4.0
    if name == 'tests':
        return 3.0
    if name.startswith('Test'):
        return 2.0
    if name == 'class':  # PHP's class-name constant
        return 5.2
    if name == 'table':  # Database table access
        return 4.3
    if name in STREAMS:
        return 2.3
    return 2.4 if name[0].islower() else 1.2


