    name = token.strip()
    tight = token == name
    identifier = bool(name) and (name[0].isalpha() or name[0] == '_')
    value = 0.0
    if prev.endswith('::'):
        if identifier:
            value = scoped_name(name) if tight else 0.4
        elif name.isdigit():
            value = 2.8
        elif name.startswith(':'):
            value = 2.2
        elif name.startswith('('):
            value = 0.8
    elif prev.endswith('->') and not prev.endswith('-->'):
