NAMES = {"new": 4.5, "json": 4.5, "test": 3.9, "create": 3.7, "get": 2.9, "fmt": 2.9}
# Weak activation on the token after these connectives.
WEAK = {"而": 0.6, "の": 0.25, "以": 0.25, "为": 0.25, "其": 0.25, "->": 0.3}


def is_cjk_ideograph(s):
    """True for a single Chinese/Japanese ideograph (CJK Unified Ideographs)."""
    return len(s) == 1 and unicodedata.name(s, "").startswith("CJK UNIFIED")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""  # a new document starts: nothing before it counts
    if prev == "::":
        if cur in NAMES:
            return carry, NAMES[cur]
        if cur[:1].islower():
            return carry, 2.3
        if cur[:1].isupper():
            return carry, 1.1
        return carry, 0.0
    if prev == "之":
        return carry, 4.5 if is_cjk_ideograph(cur) else 1.0
    return carry, WEAK.get(prev, 0.0)

