    'func': (0.40, 0.75),
    'function': (0.03, 0.54),
    'public': (0.14, 0.79),
    'private': (-0.07, 0.53),
    'protected': (-0.05, 0.52),
    'static': (0.00, 0.48),
    'void': (0.12, 0.46),
    'const': (-0.05, 0.42),
    'let': (-0.02, 0.54),
    'var': (0.00, 0.55),
    'class': (0.02, 0.34),
}
