    '.': 0.65,
    '<': 0.8,
    '</': 0.6,
    '$': 0.5,
    '[': 0.3,
    '*': 0.32,
    '-': 0.5,
    '|': 0.4,
    ':': 0.45,
    '\\': 0.34,
    '@': 0.3,
    '`': 0.32,
    '(': 0.22,
    'this': 0.45,
    'self': 0.2,
