import unicodedata

READS = ()

SMALL_TAG_RESPONSES = {
    '</tool_response>': 0.35,
    '</tool_call>': -0.145,
    '</think>': -0.12,
    '<think>': 0.07,
}
# C3/C4/C5 in Latin-1, C3 in Cyrillic CP1251, C5 in CP1250,
# and E2 in Thai CP874: recognizable misdecoded UTF-8 lead bytes.
MOJIBAKE_LEADS = frozenset('ÃГĹÄÅโ')


