    last = previous[-1:]
    word = last.isalpha()
    digit = last.isdigit()
    if s == '<|im_end|>':
        if previous == '</tool_call>':
            return -0.32 * (position / (position + 60.0)) ** 0.5
        if previous == '</tool_response>':
            return -0.59 * (position / (position + 26.0)) ** 0.5
        return -0.03 - 1.10 * (position / (position + 10.0)) ** 0.5
    if s == '<tool_call>':
        return -0.335 - 0.99 * (position / (position + 6.4)) ** 0.5
    if s in SMALL_TAG_RESPONSES:
        return SMALL_TAG_RESPONSES[s]
    if s.startswith('\\x'):
        if s == '\\xe':
            return -2.19 if word else -1.02
        if s == '\\xc':
            return -1.78 if word else -1.10
        if s == '\\xa':
            return -0.56
        return -0.90 if word else -0.81
    if s.startswith('\\u'):
        if len(s) > 2:
            return -0.50
        return -1.32 if word else -0.86
    if s in ('\\', '\\"', "\\'"):
        if word:
            return {'\\': -0.21, '\\"': -0.43, "\\'": -0.92}[s]
        return -0.10 if digit else 0.04
    if s in ("'", '"', '`'):
        if word:
            return {"'": -0.055, '"': -0.009, '`': -0.042}[s]
        return 0.03 if digit else 0.06
    if s.strip() == '&#':
        return -0.51 if s[0] != ' ' else -0.36
    if s == '&':
        return -0.17 if word else -0.02
    if s == '\\t':
