            return -1.0 if ascii_word else -0.30
        if s in {'Ã', 'Ĺ'}:
            return -2.8 if ascii_word else -0.60
        if s == 'Г':
            return -3.3 if ascii_word else -0.08
        if s == 'โ':
            return -1.35 if ascii_word else -0.13
        return -0.84 if ascii_word else -0.05
