    if token == "款式":
        return None, 1.35
    if token in {"还款", "付款"}:
        return None, 0.85
    if token == "这款游戏":
        return None, 0.7
    return None, 0.0

programs.sol:
"""Evidence, findings, and the introduction of a claim.

The main signal is 'that' after finding/proof verbs, then inference, knowledge,
and speech/belief verbs. Recent empirical sources boost evidence verbs and
result nouns; research/data organization words have negative responses.
Relative/demonstrative 'that' stays small. Test-file paths and
code assertions are a secondary positive pattern. English inflections are
recognized by ordinary suffix rules. The numbers are activation scales.
"""

READS = ()


def words(text):
    return frozenset(text.split())


PROOF = words('show find demonstrate confirm prove verify')
INFERENCE = words('indicate reveal conclude suggest discover observe estimate '
                  'determine testify report')
KNOWLEDGE = words('know see note notice realize realise recognize check learn '
                  'understand')
ASSERTION = words('claim argue announce declare assert contend ensure decide '
                  'insist allege advise inform propose recommend dictate '
                  'acknowledge clarify provide')
BELIEF = words('believe assume suppose hope wish recall remember')
SPEECH = words('say state tell write mention think explain consider')
MEANING = words('mean imply require follow')
# Baseline, recent research gain, and recent measurement gain.
VERBS = {
    'show': (0.45, 2.1, 2.0), 'reveal': (0.9, 1.2, 0.1),
    'indicate': (0.45, 1.1, 1.55), 'suggest': (0.35, 0.8, 0.7),
    'demonstrate': (0.3, 1.2, 0.5), 'discover': (0.25, 0.6, 0.0),
    'confirm': (0.0, 0.5, 0.8), 'prove': (0.0, 0.35, 0.25),
    'verify': (0.0, 0.35, 0.25), 'conclude': (0.05, 1.05, 0.05),
}
ROOTS = PROOF | INFERENCE | KNOWLEDGE | ASSERTION | BELIEF | SPEECH | MEANING
IRREGULAR = {
    'found': 'find', 'shown': 'show', 'knew': 'know', 'known': 'know',
    'seen': 'see', 'said': 'say', 'told': 'tell', 'thought': 'think',
    'wrote': 'write', 'written': 'write', 'understood': 'understand',
    'meant': 'mean', 'proven': 'prove',
}


def root(word):
    if word in IRREGULAR:
        return IRREGULAR[word]
    if word in ROOTS:
        return word
    for suffix in ('ing', 'ed', 'es', 's'):
        if word.endswith(suffix):
            stem = word[:-len(suffix)]
            for candidate in (stem, stem + 'e', stem[:-1] + 'y'):
                if candidate in ROOTS:
                    return candidate
    return word


RESEARCH = words('study studies research experiment experiments investigation '
                 'investigations survey surveys analysis analyses trial trials '
                 'researchers scientists review reviews evaluation evaluations '
                 'examination examinations 研究 调查 实验 研究报告')
MEASUREMENTS = words('data results result findings evidence observations '
                     'statistics 数据 结果 的结果 成果 数值 计算 データ')
MODIFIERS = words('experimental empirical analytical clinical laboratory '
                  'medical scientific numerical statistical observational '
                  'simulation simulations measurement measurements sample reported '
                  'recorded test tests surveillance')
PRESENTATIONS = words('figure figures fig table tables graph graphs chart charts '
                      'plot plots image images video report reports')
SOURCES = words('study studies research experiment experiments evidence data')
AUXILIARIES = words("have has had been was were also clearly recently previously "
                    "consistently repeatedly not 've ’ve")
CLAIM_NOUNS = {
    'evidence': 1.7, 'proof': 1.4, 'finding': 1.6, 'findings': 1.6,
    'fact': 0.7, 'conclusion': 0.9, 'belief': 0.7, 'possibility': 0.7,
    'suggestion': 1.2,
}
# Non-English entries name data/results and showing/learning findings.
NOUNS = {
    'data': 0.1, '_data': 0.1, 'evidence': 0.8,
    'results': 0.45, 'findings': 0.45, 'result': 0.0,
    'analysis': 0.0, 'studies': 0.0, 'research': 0.0,
    'experiments': 0.0, 'tests': 0.0,
    '数据': 0.65, '结果': 0.65, '的结果': 0.65, '成果': 0.65, 'データ': 0.65,
    '显示': 0.95, '表明': 0.95, '发现': 0.95, '证明': 0.95,
    '获悉': 1.5, '资料显示': 1.5, '指出': 0.95,
}


def empirical_subject(history):
    for word in reversed(history):
        if word in SOURCES:
            return 1.0
        if word not in AUXILIARIES and word != ',':
            break
    return 0.0


def claim_after(word):
    if word in CLAIM_NOUNS:
        return CLAIM_NOUNS[word]
    if word in ('found', 'shown', 'showed', 'demonstrated', 'confirmed'):
        return 2.4
    r = root(word)
    for group, strength in ((PROOF, 2.2), (INFERENCE, 1.45), (KNOWLEDGE, 0.9),
                            (ASSERTION, 0.9), (BELIEF, 0.7), (SPEECH, 0.5),
                            (MEANING, 0.6)):
        if r in group:
            return strength
    if word in words('clear apparent obvious sure given'):
        return 0.85
    if word in words('possible likely unlikely doubt me you us them him her out'):
        return 0.45
    if word in words('is was be been being are were so except'):
        return 0.2
    return 0.5 if word == 'such' else 0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry and carry[0] == doc else ()
    raw = prefix.token_strings[-1]
    word = raw.strip().lower().lstrip('-/._')
    previous = history[-1] if history else ''
    r, prev_root = root(word), root(previous)
    context = []
    for group in (RESEARCH, MEASUREMENTS, MODIFIERS, PRESENTATIONS):
        context.append(max((d for w, d in zip(reversed(history),
                            (1.0, 0.85, 0.6, 0.4)) if w in group), default=0.0))
    research, measurements, modifiers, presentation = context
    value = 0.0
    if word == 'that':
        value = claim_after(previous) + 0.45 * research + 0.35 * measurements
        if prev_root in PROOF | INFERENCE:
            value += 0.5 * research + 0.2 * measurements
        if previous in words('of in on at for from with than and but or if'):
            value -= 0.2
        elif not previous.isalpha():
            value -= 0.2
        if previous in words('thing things something anything everything nothing'):
            value -= 0.35
        if raw.strip() == 'That':
            value -= 0.1
    if r in VERBS or word == 'found':
        base, r_gain, m_gain = VERBS.get(r, (0.55, 1.8, 0.0))
        if word == 'shown':
            base, r_gain, m_gain = 0.3, 2.05, 0.1
        if word == 'showed':
            base, r_gain, m_gain = 1.05, 0.8, 0.8
        value = base + r_gain * research + m_gain * measurements
        value += 1.1 * modifiers + 0.95 * presentation
        if r in words('show find reveal indicate suggest'):
            value += 1.85 * empirical_subject(history)
        if previous in ('been', 'was', 'were', 'has', 'have', "'ve", '’ve'):
            value += 0.7
        if word == 'found' and previous in ('be', 'is', 'are'):
            value -= 0.35
    if word in NOUNS:
        value = NOUNS[word] + 1.3 * research + 0.5 * measurements + 1.25 * modifiers
    if word in ('studies', 'research') and previous in ('recent', 'previous',
                                                       'prior', 'earlier'):
        value += 0.5
    if word in ('obtained', 'collected', 'detected', 'identified', 'observed'):
        value = 0.1 + 1.3 * research + 0.5 * measurements + 1.2 * modifiers
    if word == 'out' and prev_root in ('find', 'check'):
        value = 0.85
    if word == 'to':
        if previous == 'found':
            value = 1.8
        elif previous in ('shown', 'proved', 'proven', 'confirmed', 'demonstrated'):
            value = 1.4
        elif previous in ('reported', 'determined', 'observed'):
            value = 0.85
        elif prev_root in VERBS or previous in ('known', 'compared'):
            value = 0.35
    if previous == 'evidence':
        value += {'of': 0.7, 'for': 1.3, 'to': 0.7}.get(word, 0.0)
    if word in ('on', 'into') and previous in RESEARCH:
        value += 0.9
    organization = words('design plan plans area areas ethics structure structures '
                         'infrastructure guides name types suites privacy protection '
                         'resources')
    if word in organization and previous in RESEARCH | MEASUREMENTS | MODIFIERS:
        value = -1.25
    if word in ('has', 'have') and previous in RESEARCH | MEASUREMENTS:
        value = 0.6
    if raw.lower() in ('/test', '/tests', '.test'):
        value = (0.15 if raw.startswith('.') else 0.3)
        if previous == 'tests':
            value += 1.7
    if raw.startswith('.assert'):
        value = 1.2
    return (doc, (history + (word,))[-4:]), float(value)

"""Mainly eight: the digit, eight-family words, and the eighth month.

Eight is weaker inside numbers or decimals and stronger in identifiers,
particularly UTF-8 and integer-width suffixes. A second response catches
let's and the short personal constructions 'you want', 'I think', and
'let me know'. Unrecognized tokens receive a near-zero prediction.
"""
import re

READS = ()
EIGHT_FAMILY = {
    'eight': 0.70, 'eighth': 0.62, 'eighty': 0.54,
    'eighteen': 0.33, 'viii': 0.43, '八': 1.02,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail, position = '', '', 0
    if carry is not None and carry[0] == doc:
        _, previous, tail, position = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = -0.001
    if word.lstrip('-') in EIGHT_FAMILY:
        value = EIGHT_FAMILY[word.lstrip('-')]
        if token == ' Eight':
            value = 0.86
    elif token.strip() in {'August', 'Aug', 'AUG'}:
        value = 0.52 if token.strip() == 'August' else 0.33
        if not token.startswith(' '):
            value -= 0.10
    elif word in {'8', '８'}:
        value = 0.64 + 0.30 / (position + 1)
        if position == 0:
            value = 0.76
        elif tail.endswith('.'):
            value -= 0.15
        elif previous in set('0123456789'):
            value -= 0.07 if int(previous) % 2 == 0 else 0.025
        elif tail and tail[-1].isalpha():
            value += 0.18
        elif tail.endswith(('-', '/')):
            value += 0.09
        if tail.endswith('\\x'):
            value = 0.72
        elif re.search(r'(?i)(?:utf[-_]|u?int)$', tail):
            value = 1.12
    elif token in {"'s", '’s'} and previous == 'let':
        value = 1.35 if token == "'s" else 1.23
    elif token == ' lets':
        value = 0.41
    elif token in {' want', ' think', ' know'}:
        value = {'want': 0.15, 'think': -0.23, 'know': -0.21}[word]
        if previous == 'i':
            value += 0.11
        elif previous == 'you':
            value = {'want': 0.62, 'think': 0.24, 'know': 0.14}[word]
        elif previous in {'we', 'they'}:
            value += 0.28
        elif previous == 'to':
            value -= 0.18
        elif previous in {"'t", '’t', 'not'}:
            value += 0.07
        elif previous in {"'s", '’s', 'just'}:
            value -= 0.30
        elif previous in {'will', 'would'}:
            value -= 0.10
        elif previous in {'me', 'us', 'them'}:
            value = -0.78 if word == 'think' else -0.25
            if word == 'know':
                value = {'me': -1.19, 'us': -0.81, 'them': -0.67}[previous]
    return (doc, word, (tail + token)[-32:], position + 1), float(value)

programs.haiku:
"""Layer-0 MLP feature that writes "the number eight" and "let's" into the residual stream.

What it does, in plain terms (the value is the component's activation at that token):
- The number eight, in any written form, gives about +0.6: the digit "8", "eight",
  "Eight", Roman "VIII", the Chinese numeral "八", and "August"/"Aug" (the eighth month).
- The "'s" of "let's" (an apostrophe-s right after "let" or "Let") gives about +1.35,
  the strongest response of this feature.
- A few verbs get small effects: mental verbs (know, think, thought, wonder, mind, ask)
  about -0.2; "know" in "let me know" about -1.2; want, wants, got about +0.2.
- Everything else gives 0.

Positions are read one token at a time, and the previous token is only used within the
same document.
"""

READS = ()

EIGHT_WORDS = {"8", "eight", "Eight", "八", "VIII", "August", "Aug", "eighth"}
MENTAL_VERBS = {"know", "think", "thinking", "thought", "mind", "wonder", "wondered", "ask"}
WANT_VERBS = {"want", "wants", "got"}
APOSTROPHE_S = {"'s", "’s"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in EIGHT_WORDS:
        return carry, 0.6
    if word in APOSTROPHE_S and before == "let":
        return carry, 1.35
    if word == "know" and before == "me":
        return carry, -1.2
    if word in MENTAL_VERBS:
        return carry, -0.2
    if word in WANT_VERBS:
        return carry, 0.2
    return carry, 0.0

programs.sol:
"""Approximate protocol-boundary pulses and Arabic word-piece responses.

New messages, tool-call endings and tool-result openings give strong pulses;
checkmarks give smaller ones. Space-prefixed Arabic pieces respond strongly,
especially single letters. Article prefixes and common function words are
weaker; continuations after short clitics are boosted. Recent Persian/Urdu
letterforms usually suppress the Arabic response. All other tokens give zero.
The 80-character history and previous token reset at document boundaries.
"""
READS = ()

BOUNDARIES = {
    '<|im_start|>': 1.99,
    '<|im_end|>': -0.28,
    '</tool_call>': 2.84,
    '<tool_response>': 1.58,
    '</tool_response>': 0.15,
    '<think>': 0.52,
    '</think>': 0.36,
}
PERSIAN_URDU_LETTERS = frozenset('پچژگکیٹڈڑںھہہےۀ')
ARABIC_FORMS = frozenset('أإةىيكؤئ')
PREPOSITIONS = frozenset('في من على إلى عن مع بعد قبل بين عند خلال فى علي الى'.split())
PRONOUNS = frozenset('ما هذا هذه ذلك تلك الذي التي هو هي هم أنا أنت نحن'.split())
CONNECTIVES_AND_NEGATION = frozenset('لا لم لن إن أن أو بل كما أنه ومن وفي ولكن'.split())
QUANTIFIERS = frozenset('كل بعض جميع'.split())
CLITICS = frozenset('و ل ب ف ك وب ول'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous = '', ''
        first = True
    else:
        _, recent, previous = carry
        first = False
    token = prefix.token_strings[-1]
    recent = (recent + token)[-80:]
    value = BOUNDARIES.get(token, 0.0)
    if token == '<|im_start|>' and first:
        value = 1.08
    elif token == '<|im_end|>' and previous == '</tool_call>':
        value = 0.28
    elif token == '</tool_call>' and (first or previous == '<tool_call>'):
        value = 1.75
    elif token.strip() == '✓':
        value = 1.02 if token.startswith(' ') else 0.64
    else:
        word = token.strip()
        is_arabic = word and all(
            '\u0621' <= c <= '\u065f' or c in PERSIAN_URDU_LETTERS
            for c in word
        )
        if is_arabic:
            persian = (
                any(c in PERSIAN_URDU_LETTERS for c in recent)
                and not any(c in 'أإة' for c in token)
            )
            known_arabic = any(c in ARABIC_FORMS for c in recent)
            length = len(word)
            if persian:
                if not token.startswith(' '):
                    after_clitic = (
                        previous.startswith(' ') and previous.strip() in CLITICS
                    )
                    value = 0.24 if after_clitic else 0.0
                elif length > 1:
                    value = 0.25
                elif word in PERSIAN_URDU_LETTERS:
                    value = 0.25
                elif word in 'اوهآ':
                    value = 0.5
                else:
                    value = 1.2
            elif token.startswith(' '):
                if word.startswith(('ال', 'وال', 'بال', 'لل', 'كال')):
                    value = max(0.1, 1.65 - 0.27 * length)
                elif length == 1:
                    value = 4.5
                    if word in 'ول':
                        value = 2.85
                    elif word in 'اي':
                        value = 3.5
                    elif word in 'بفك':
                        value = 3.85
                    elif word == 'إ':  # Alif with hamza below.
                        value = 5.8
                elif word in PREPOSITIONS:
                    value = 1.85
                elif word in PRONOUNS:
                    value = 1.3
                elif word in CONNECTIVES_AND_NEGATION:
                    value = 2.4
                elif word in QUANTIFIERS:
                    value = 3.5
                elif word.startswith('است'):
                    value = 1.2
                else:
                    value = {2: 3.2, 3: 2.35}.get(length, 1.85)
                    if length <= 3 and word.startswith(('ت', 'م')):
                        value += 1.0
            else:
                value = 0.7 if length <= 2 else 0.57
                if previous.startswith(' '):
                    if previous.strip() in CLITICS:
                        value = 2.1
                    elif len(previous.strip()) == 1:
                        value = 1.3
            if not persian and not known_arabic:
                value *= 0.65
    return (doc, recent, token), float(value)

programs.luna:
"""Predict control markers and the component's positive Arabic-script signal."""

READS = ()


def has_arabic_letter(text):
    return any(
        char.isalpha()
        and (
            "\u0600" <= char <= "\u06ff"
            or "\u0750" <= char <= "\u077f"
            or "\u08a0" <= char <= "\u08ff"
        )
        for char in text
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else None

    if token == "<|im_start|>":
        value = 1.08 if previous == "<|endoftext|>" else 1.95
    elif token == "</tool_call>":
        value = 2.84
    elif token == "<tool_response>":
        value = 1.59
    elif token == "<|im_end|>":
        value = 0.32 if previous == "</tool_call>" else -0.4
    elif token == "<think>":
        value = 0.59
    elif token == "</think>":
        value = 0.46
    elif token == "</tool_response>":
        value = 0.30
    elif token == " ✓":
        value = 1.15
    elif has_arabic_letter(token):
        value = 0.9
    else:
        value = 0.0

    return (doc, token), value

programs.sol:
"""A local lexical detector centred on 目: eye, item, and purpose.

It responds most to 目 and its compounds, Japanese 'me', and Korean 'mok'.
A smaller multilingual vocabulary covers purposes, projects, programmes,
subjects, and items.  Spelling and token boundaries affect the strength.
Only a few word-completion and compound rules use the previous token;
this is not a detector of the document's overall topic.
"""

import re

READS = ()

# Compounds of 目: eye; purpose; project/item; subject; programme; contents.
EYE_COMPOUNDS = {
    '目': 6.86, '目的': 4.55, '项目': 3.0, '項目': 3.75,
    '科目': 2.93, '题目': 2.90, '节目': 2.75, '栏目': 3.2,
    '目前': 0.86, '目录': 1.94, '目標': 1.23, '目标': 0.91,
    '目的地': 1.08, '的目的': 3.47, '目的是': 2.70,
    '项目的': 2.72, '目の': 4.62, '目に': 4.84, 'を目': 3.3,
    '数目': 1.79, '面目': 1.63, '目光': 1.03,
}

# Japanese me spellings; Korean/Vietnamese cognates of 目.
# 木 (wood) is a Chinese homophone of 目.
READINGS = {
    'め': 2.33, 'める': 0.92, 'めて': 0.45, 'めた': 1.52,
    '목': 3.82, '목적': 2.54, 'mục': 3.09, '木': 0.88,
}

PURPOSE_WORDS = {
    'purpose': 1.89, 'purposes': 2.34,
    'objective': 1.11, 'objectives': 1.49,
    'goal': 0.46, 'goals': 0.55, 'aim': 0.43, 'aims': 0.51,
    'aimed': 0.62, 'sake': 1.04,
    'цель': 0.67, 'целью': 0.59, 'objetivo': 0.55,
    '用途': 1.27, '宗旨': 0.62,
}
ITEM_WORDS = {
    'item': 0.71, 'items': 0.77,
    'program': 0.80, 'programs': 0.80,
    'programme': 0.95, 'programmes': 0.85,
    'project': 0.69, 'projects': 0.62,
    'subject': 0.77, 'subjects': 0.61,
    'contents': 0.98, 'content': 0.15,
    'entitled': 0.59, 'titled': 0.73, 'headed': 0.58,
    'agenda': 0.53, 'subjected': 0.39,
    'предмет': 1.16, 'проект': 0.34, 'программ': 0.54,
    'программы': 0.57, 'objet': 0.50,
    '内容': 0.33, '內容': 0.49, '课题': 1.06,
    '物品': 0.58, '名称': 0.30, 'メニュー': 1.22,
    'アイテム': 0.39, 'もの': 0.56, 'ものを': 0.48, 'ものが': 0.51,
}


def lexical(token):
    word = token.strip()
    if word in EYE_COMPOUNDS:
        return EYE_COMPOUNDS[word]
    if '目' in word:
        if '项目' in word:
            return 2.3 if len(word) <= 4 else 1.3
        if '目标' in word:
            return 0.8
        return 0.9
    if word in READINGS:
        if word == '목' and token.startswith(' '):
            return 5.4
        return READINGS[word]
    bare = word.lstrip('._-/(:')
    lower = bare.lower()
    value = PURPOSE_WORDS.get(lower, ITEM_WORDS.get(lower, 0.0))
    if lower == 'purpose':
        if word.startswith('-'):
            value = 1.28
        elif bare[:1].isupper() and not bare.isupper():
            value = 2.3
    if lower == 'contents':
        if bare[:1].isupper():
            value = 2.49
        elif not token.startswith(' '):
            value = 1.5
    if lower == 'project':
        if not token.startswith(' '):
            value = 0.3
        elif bare[:1].isupper():
            value = 0.4
    if lower == 'item' and token == 'item':
        value = 0.55
    if lower in ('wood', 'wooden', 'eye'):
        value = {'wood': 0.25, 'wooden': 0.66, 'eye': 0.20}[lower]
    # Identifier spellings of list items and project IDs.
    if not value and re.search(r'(?:[Ii]tem(?:s|Id|List|Type)?|[Pp]rojectId)$', bare):
        value = 0.62
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    value = lexical(token)
    if word == '目' and previous.endswith(('注', '見た')):
        value = 4.2  # attention / appearance, rather than a standalone eye
    if word == '목' and previous.endswith('제'):
        value = 2.9  # the compound 제목, title
    if word.lower() in ('ive', 'ives') and previous.lower().endswith('object'):
        value = 1.1 if word.lower() == 'ive' else 1.5
    if word == 'of':
        if previous.lower().strip() == 'objective':
            value = 0.55
        elif previous.lower().strip() == 'purpose':
            value = 0.28
    # A byte fragment can finish 目 even though decoded alone it is U+FFFD.
    if '\ufffd' in token and prefix.text_prefixes[-1].endswith('目'):
        value = 8.2
    return (doc, token), float(value)

programs.haiku:
"""Lexicon of words for purpose, aim, item, program and subject. Strongest on the CJK character
目 (eye), and its Korean (목) and Japanese (め) readings, inside words such as 目的 (purpose).
English purpose and objective words respond moderately, item, program, project and subject
words weakly, and "of" right after "purpose" or "objective" weakly. Everything else is 0."""
READS = ()

EYE = {"目": 6.5, " 목": 5.0, "목": 4.0, "め": 2.3, "木": 0.9}
PURPOSE = {" purpose", " purposes", " Purpose", " PURPOSE", "Purpose"}
OBJECTIVE = {" objective", " objectives", " Objective", "Objective", "objective"}
ITEM = {" program", " programs", " programme", " project", " projects", " item", " items", "item", "items",
        "Item", " subject", " subjects", " Program", " Contents", "Contents", " contents", " Content", "Content"}
GOAL = {" goal", " goals", " aim", " aims", " aimed", " Goal"}
WEAK_EYE = {"目前", "目标", "目標", "目光", "目的地"}
AFTER_PURPOSE = {" of", " of the", " of this"}


def value(s):
    if s in EYE:
        return EYE[s]
    if s in WEAK_EYE:
        return 1.0
    if "目的" in s:
        return 4.5
    if "目" in s:
        return 2.5
    if s in PURPOSE:
        return 2.0
    if s in OBJECTIVE:
        return 1.0
    if s in ITEM:
        return 0.75
    if s in GOAL:
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings
    v = value(s[-1])
    # the word after "purpose" or "objective" ("of") responds weakly
    if v == 0.0 and s[-1] == " of" and len(s) > 1 and (s[-2] in PURPOSE or s[-2] in OBJECTIVE):
        v = 0.5
    return None, float(v)

programs.sol:
"""Estimate a horizontal-punctuation response, strongest on separated dashes.

Recent hyphens inhibit dashes, especially repetitions of the same form.
Digit adjacency, token-initial capitals, and recent typographic dashes boost
single dashes. Indentation and code-like punctuation lower the estimate.
Simple shape rules cover arrows, ellipses, and other horizontal marks.
Unrecognized tokens, including ordinary words, produce zero. All history
resets at document boundaries. These are proxies, not an exact lexical model.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, last_dash, previous = 0, -10000, ''
        plain = separated = -10000
        hyphens = typographic = style = 0.0
    else:
        (_, position, last_dash, previous, plain, separated,
         hyphens, typographic, style) = carry
    token = prefix.token_strings[-1]
    mark = token.strip()
    spaced = token.startswith(' ')
    prev = previous.strip()
    indentation = previous.isspace()
    symbol = bool(prev) and not any(c.isalnum() for c in prev)
    digit = prev.isdigit()
    capital = prev[:1].isupper()
    # Inverse-square-root recency fades smoothly with token distance.
    recent = (position - last_dash) ** -0.5
    initial = (position + 1) ** -0.5
    same = (position - (separated if spaced else plain)) ** -0.5
    value = 0.0

    if mark == '-':
        if spaced:
            value = (1.27 - 0.32 * recent - 0.76 * same - 0.02 * hyphens
                     + 0.44 * initial + 0.78 * style + 0.29 * typographic
                     + 0.08 * digit + 0.08 * capital
                     - 0.88 * indentation - 0.09 * symbol)
            if position == 0:
                value -= 1.0
        else:
            value = (0.50 - 0.41 * recent - 0.31 * same - 0.02 * hyphens
                     - 0.25 * initial + 0.25 * style + 0.06 * typographic
                     + 0.22 * digit + 0.11 * capital + 0.06 * symbol)
            if position == 0:
                value -= 0.37
        if '\n' in token:
            value *= 0.8
    elif mark == '->':
        value = 0.79 - 0.36 * indentation - 0.26 * symbol if spaced else 0.43
    elif mark in {'<-', '-->', '<--'}:
        value = 0.37
    elif mark == '--':
        if spaced:
            value = (0.48 - 0.56 * recent - 0.02 * hyphens
                     + 0.30 * style
                     - 0.12 * indentation + 0.17 * symbol)
        else:
            value = (0.72 - 0.41 * recent - 0.06 * hyphens
                     + 0.30 * style
                     - 0.20 * indentation - 0.13 * symbol)
    elif mark and set(mark) == {'-'}:
        value = 0.0 if spaced else 0.17
    elif mark and set(mark) == {'.'} and len(mark) >= 2:
        if len(mark) == 3:
            value = 0.64 if spaced else 0.75
            if '\n' in token:
                value = 0.27
        else:
            value = 0.14 if len(mark) == 2 else 0.38
    elif mark and set(mark) == {'·'} and len(mark) >= 2:
        value = 0.17
    elif mark == '~':
        value = 0.32
    elif mark.endswith('-') and not any(c.isalnum() for c in mark):
        value = 0.33 if spaced else 0.51
        if mark.startswith('.') or mark.startswith(':'):
            value = 0.70
    elif mark in {'…', '—', '–'}:
        value = -0.04 if spaced else 0.12
    elif mark in {'−', '⁻'}:
        value = 0.35 if mark == '⁻' else 0.13

    # Decaying counts summarize roughly the last 20--30 tokens, not the whole row.
    hyphens = 0.969 * hyphens + ('-' in token)
    typographic = (0.969 * typographic
                   + any(c in token for c in '—–−'))
    code_symbol = (not any(c.isalpha() for c in token)
                   and any(c in token for c in '{};[]='))
    # A compact contrast between title-like capitalization and code symbols.
    style = 0.95 * style + 0.05 * (mark[:1].isupper() - 2 * code_symbol)
    if mark == '-':
        if spaced:
            separated = position
        else:
            plain = position
    if '-' in token:
        last_dash = position
    state = (doc, position + 1, last_dash, token, plain, separated,
             hyphens, typographic, style)
    return state, float(value)
